        'fix.closeProcess.done'      = 'Closed {0}'
        'fix.emptyTemp'              = 'Delete temporary files ({0} GB)'
        'fix.emptyTemp.done'         = 'Deleted temporary files'
        'fix.emptyRecycleBin'        = 'Empty the Recycle Bin ({0} GB)'
