        'ins.notAdmin'     = 'This account is not an administrator: many programs ask for an administrator password'
        'ins.reboot'       = 'A restart is waiting: some installers refuse until then'
        'hij.policy'       = '{0} is "managed by your organisation" with rules for the search engine, start page or add-ons: {1}'
        'hij.policyOther'  = '{0} has {1} rule(s) from a settings tool, none about the search engine, start page or add-ons'
        'hij.search'       = '{0} searches with {1}: not a search engine people choose themselves'
        'hij.searchOk'     = '{0} searches with {1}'
