# the sound, not about A1 "Geen internet").
$script:HcSearchStop = @('geen', 'niet', 'niks', 'het', 'de', 'een', 'en', 'of', 'mijn', 'is', 'doet', 'werkt', 'meer', 'wil', 'kan', 'ik', 'op', 'van', 'te',
    'no', 'not', 'the', 'a', 'an', 'my', 'does', 'doesnt', 'dont', 'work', 'works', 'will', 'wont', 'cant', 'any', 'and', 'or', 'it')

function ConvertTo-HcSearchText {
    param([string]$Text)
    $d = "$Text".ToLowerInvariant().Normalize([Text.NormalizationForm]::FormD)
    $plain = -join @($d.ToCharArray() | Where-Object { [Globalization.CharUnicodeInfo]::GetUnicodeCategory($_) -ne 'NonSpacingMark' })
    $plain -replace '[^a-z0-9]+', ' '
}

<#
    Pure: the problems that match what was typed, best first. A code ("c1")
    is an exact hit. Otherwise every word is looked up in the problem's
    name (both languages, 3 points), its own words above (2) and its
    area's name and checks (1: "anydesk" is in all of F's checks, but only
    F2 is about it); a word of 3+ letters also matches the start of a
    longer one ("print" finds "printer"). The most points win; ties keep the
    menu order.
#>
function Get-HcProblemMatches {
    param([string]$Query, [string[]]$Codes)
    $all = @((ConvertTo-HcSearchText $Query) -split ' ' | Where-Object { $_ })
    if (-not $all.Count) { return @() }
    $exact = @($Codes | Where-Object { $_.ToLowerInvariant() -eq ($all -join '') })
    if ($exact.Count) { return $exact }
    $words = @($all | Where-Object { $script:HcSearchStop -notcontains $_ })
    if (-not $words.Count) { return @() }
    $scored = for ($i = 0; $i -lt $Codes.Count; $i++) {
        $code = $Codes[$i]
        $letter = $code.Substring(0, 1)
        $title = @((ConvertTo-HcSearchText ("$($script:Strings.en["problem.$code"]) $($script:Strings.nl["problem.$code"])")) -split ' ' | Where-Object { $_ })
        $own = @((ConvertTo-HcSearchText $script:HcProblemWords[$code]) -split ' ' | Where-Object { $_ })
        $rest = @((ConvertTo-HcSearchText ("$($script:Strings.en["area.$letter"]) $($script:Strings.nl["area.$letter"]) $($script:Strings.en["looks.$letter"]) $($script:Strings.nl["looks.$letter"])")) -split ' ' | Where-Object { $_ })
        $score = 0
        foreach ($q in $words) {
            $match = { param($list) @($list | Where-Object { $_ -eq $q -or ($q.Length -ge 3 -and $_.StartsWith($q)) }).Count -gt 0 }
            if (& $match $title) { $score += 3 } elseif (& $match $own) { $score += 2 } elseif (& $match $rest) { $score += 1 }
        }
        if ($score) { [pscustomobject]@{ Code = $code; Score = $score; Index = $i } }
    }
    @($scored | Sort-Object @{ Expression = { $_.Score }; Descending = $true }, @{ Expression = { $_.Index } } | ForEach-Object { $_.Code })
}

# The right-hand column: whatever $HcWin.View says is on it.
function Update-HcResult {
    $w = $script:HcWin
    # The phone tab has its own right-hand column, drawn the same way.
    $panel = $w.Window.FindName($(if ($w.Tab -eq 'phone') { 'PhoneResultPanel' } else { 'ResultPanel' }))
    $panel.Children.Clear()
    $add = { param($element) [void]$panel.Children.Add($element) }

    if ($w.Code -and $w.View -in @('input', 'busy', 'report')) {
        & $add (New-HcText ($w.Code + '  ' + (T "problem.$($w.Code)")) 19 'Text' -Bold -Margin @(0, 0, 0, 10))
    } elseif ($w.View -eq 'checkall') {
        & $add (New-HcText (T 'win.checkAll') 19 'Text' -Bold -Margin @(0, 0, 0, 10))
    } elseif ($w.View -eq 'changes') {
        & $add (New-HcText (T 'win.changes.title') 19 'Text' -Bold -Margin @(0, 0, 0, 10))
    } else {
        & $add (New-HcText (T 'win.result') 19 'Text' -Bold -Margin @(0, 0, 0, 10))
    }
    if ($w.Banner) { & $add (New-HcText $w.Banner 14.5 'Ok' -Bold) }
    if ($w.Notice) { & $add (New-HcText $w.Notice 14.5 'Warn' -Bold) }
    if ($w.UndoAsk) { & $add (New-HcQuestion (T 'win.undoConfirm' $w.UndoAsk) 'undoYes' 'undoNo') }

    switch ($w.View) {
        'empty' {
            & $add (New-HcText $(if ($w.Tab -eq 'phone') { T 'ph.pick' } else { T 'win.pick' }) 15 'Soft')
        }
        'input' {
            $ask = switch ($w.Code) { 'A3' { T 'site.ask' } 'M8' { T 'pair.ask' } default { T 'mail.ask' } }
            & $add (New-HcText $ask 15 'Text')
            $box = New-Object Windows.Controls.TextBox
            $box.FontSize = 16
            $box.Padding = New-HcThickness @(6, 5, 6, 5)
            $box.Margin = New-HcThickness @(0, 4, 0, 10)
            $box.Text = "$($w.Input)"
            $box.Tag = @{ Do = 'input' }
            $box.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'Bg')
            $box.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Text')
            $box.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Hi')
            $box.SetResourceReference([Windows.Controls.TextBox]::CaretBrushProperty, 'Text')
            $box.Add_KeyDown({ if ($_.Key -eq 'Return') { Invoke-HcClick $this } })
            & $add $box
            & $add (New-HcButton (T 'win.check') @{ Do = 'input' } 'HcPrimary')
            $w.InputBox = $box
            [void]$box.Focus()
        }
        'busy' {
            & $add (New-HcText $w.BusyText 15 'Soft')
            $bar = New-Object Windows.Controls.ProgressBar
            $bar.IsIndeterminate = $true
            $bar.Height = 6
            $bar.Margin = New-HcThickness @(0, 6, 0, 0)
            $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
            & $add $bar
        }
        'report' { Add-HcReportView $panel }
        'checkall' { Add-HcCheckAllView $panel }
        'changes' { Add-HcChangesView $panel }
    }
}

<#
    Every change of this visit, newest first: what it did, when, and
    whether it is still active. An active one can be undone (unless a later
    change of the same thing has to go first), an undone one can be done
    again; a fix without an undo says so. Each asks Ja/Nee first.
#>
function Add-HcChangesView {
    param($Panel)
    $w = $script:HcWin
    $add = { param($element) [void]$Panel.Children.Add($element) }
    $busy = Test-HcBusy
    $log = @($script:HcChangeLog)
    if (-not $log.Count) { & $add (New-HcText (T 'win.changes.none') 15 'Soft'); return }
    & $add (New-HcText (T 'win.changes.intro') 14 'Soft' -Margin @(0, 0, 0, 10))
    if (@($script:HcChanges | Where-Object { $script:Fixes[$_.FixId].Undo }).Count -gt 1) {
        $all = New-HcButton (T 'win.changes.undoAll') @{ Do = 'undo' }
        $all.IsEnabled = -not $busy
        $all.HorizontalAlignment = 'Left'
        $all.Margin = New-HcThickness @(0, 0, 0, 12)
        & $add $all
    }
    for ($i = $log.Count - 1; $i -ge 0; $i--) {
        $c = $log[$i]
        $fix = $script:Fixes[$c.FixId]
        $active = $c.State -eq 'active'
        $stack = New-Object Windows.Controls.StackPanel
        $head = New-Object Windows.Controls.DockPanel
        $time = New-HcText $c.Time.ToString('HH:mm') 13 'Soft' -Bold -Margin @(0, 1, 10, 0)
        [Windows.Controls.DockPanel]::SetDock($time, 'Left')
        [void]$head.Children.Add($time)
        $chip = New-HcText $(if ($active) { T 'win.changes.active' } else { T 'win.changes.undone' }) 12 $(if ($active) { 'Ok' } else { 'Soft' }) -Bold -Margin @(8, 1, 0, 0)
        [Windows.Controls.DockPanel]::SetDock($chip, 'Right')
        [void]$head.Children.Add($chip)
        $label = New-HcText $c.Label 14.5 $(if ($active) { 'Text' } else { 'Soft' }) -Margin @(0, 0, 0, 0)
        if (-not $active) { $label.TextDecorations = [Windows.TextDecorations]::Strikethrough }
        [void]$head.Children.Add($label)
        [void]$stack.Children.Add($head)

        $button = $null
        if ($active -and -not $fix.Undo) {
            [void]$stack.Children.Add((New-HcText (T 'win.changes.noUndo') 13 'Soft' -Margin @(0, 6, 0, 0)))
        } elseif ($active) {
            $button = New-HcButton (T 'win.changes.undo') @{ Do = 'changeAsk'; Index = $i; Kind = 'undo' }
            if (Test-HcChangeBlocked $c $log) {
                $button.IsEnabled = $false
                [void]$stack.Children.Add((New-HcText (T 'win.changes.laterFirst') 13 'Soft' -Margin @(0, 6, 0, 0)))
            }
        } else {
            $button = New-HcButton (T 'win.changes.redo') @{ Do = 'changeAsk'; Index = $i; Kind = 'redo' }
            if ($fix.Admin -and -not $script:IsAdmin) {
                $button.IsEnabled = $false
                [void]$stack.Children.Add((New-HcText (T 'win.changes.adminRedo') 13 'Soft' -Margin @(0, 6, 0, 0)))
            }
        }
        if ($button) {
            if ($busy) { $button.IsEnabled = $false }
            $button.HorizontalAlignment = 'Left'
            $button.Margin = New-HcThickness @(0, 8, 0, 0)
            [void]$stack.Children.Add($button)
        }
        if ($w.ChangeAsk -and $w.ChangeAsk.Index -eq $i) {
            $question = if ($w.ChangeAsk.Kind -eq 'undo') { T 'win.changes.askUndo' $c.Label } else { T 'win.changes.askRedo' (T ('fix.' + $c.FixId) $c.Target.Label) }
            [void]$stack.Children.Add((New-HcQuestion $question 'changeYes' 'changeNo'))
        }
        $box = New-HcBox '' @($stack) $(if ($active) { 'Panel' } else { 'Side' })
        $box.BorderThickness = New-HcThickness @(1, 1, 1, 1)
        $box.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'Line')
        $box.Margin = New-HcThickness @(0, 0, 0, 8)
        & $add $box
    }
}

# Ja on one change in the history: undo it, or do it again, on the worker.
function Start-HcChangeStep {
    $w = $script:HcWin
    $ask = $w.ChangeAsk
    $w.ChangeAsk = $null
    if (-not $ask -or (Test-HcBusy)) { return }
    $change = @($script:HcChangeLog)[$ask.Index]
    if (-not $change) { return }
    if ($script:DryRun) { $w.Notice = T 'fix.dryRun'; Update-HcResult; return }
    $w.Banner = T 'win.changes.working' $change.Label
    $w.Notice = $null
    if ($ask.Kind -eq 'undo') {
        Add-HcJob @{ Kind = 'undo'; FixId = $change.FixId; Target = $change.Target; Change = $change; Step = 'undo'; Done = 'Complete-HcChangeStep' }
    } else {
        Add-HcJob @{ Kind = 'fix'; FixId = $change.FixId; Target = $change.Target; Change = $change; Step = 'redo'; Done = 'Complete-HcChangeStep' }
    }
    Update-HcSide
    Update-HcResult
}

function Complete-HcChangeStep {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $c = $Job.Change
    $w.Banner = $null
    if ($ErrorText) {
        $w.Notice = if ($Job.Step -eq 'undo') { T 'undo.failed' $c.Label } else { T 'fix.failed' $ErrorText }
    } elseif ($Job.Step -eq 'undo') {
        Set-HcChangeUndone $c
        $w.Banner = T 'undo.done' $c.Label
    } else {
        Set-HcChangeRedone $c
        $w.Banner = T 'win.changes.redone' $c.Label
    }
    $w.View = 'changes'
    # A phone change: its tab reads the device again.
    if ($c.Target.Serial -and $w.Ph) { $w.Ph.Stage = 'new' }
    Update-HcSide
    Update-HcResult
}

function New-HcQuestion {
    param([string]$Text, [string]$Yes, [string]$No, [hashtable]$Extra = @{})
    $buttons = New-Object Windows.Controls.StackPanel
    $buttons.Orientation = 'Horizontal'
    $yesTag = @{ Do = $Yes } + $Extra
    $yesButton = New-HcButton (T 'win.yes') $yesTag 'HcPrimary'
    $yesButton.MinWidth = 90
    $yesButton.Margin = New-HcThickness @(0, 4, 8, 0)
    $noButton = New-HcButton (T 'win.no') @{ Do = $No }
    $noButton.MinWidth = 90
    $noButton.Margin = New-HcThickness @(0, 4, 0, 0)
    [void]$buttons.Children.Add($yesButton)
    [void]$buttons.Children.Add($noButton)
    New-HcBox '' @((New-HcText $Text 15 'Text' -Bold -Margin @(0, 0, 0, 2)), $buttons) 'Side'
}

function Add-HcReportView {
    param($Panel)
    $w = $script:HcWin
    $r = $w.Report
    $add = { param($element) [void]$Panel.Children.Add($element) }
    if ($w.FromAll) { & $add (New-HcButton (T 'win.backToAll') @{ Do = 'backToAll' }) }

    foreach ($line in @($r.Results)) {
        $brush = if ($line.Status -eq 'skipped') { 'Soft' } else { 'Text' }
        & $add (New-HcLine $line.Status $line.Text $brush)
    }
    if ($r.FindingId) {
        $findingArgs = @('finding.' + $r.FindingId) + @($r.FindingArgs)
        & $add (New-HcBox (T 'run.found') @(New-HcText (T @findingArgs) 15 'Text' -Margin @(0, 0, 0, 2)))
        $advice = T ('advice.' + $r.FindingId)
        if ($advice -notmatch '^\[') {
            & $add (New-HcText (T 'run.advice') 13 'Soft' -Bold -Margin @(0, 2, 0, 2))
            & $add (New-HcText $advice 15 'Text' -Margin @(0, 0, 0, 10))
        }
        # "Choose G2 to check OneDrive": the other problem one click away.
        foreach ($other in @(Get-HcMentionedCodes ((T @findingArgs) + ' ' + $advice) $w.Code)) {
            & $add (New-HcButton ((T 'win.open' $other) + '  ' + (T "problem.$other")) @{ Do = 'problem'; Code = $other })
        }
    }

    $actions = @($r.Actions)
    $steps = @(Get-HcSteps $r)
    if ($actions.Count -or $steps.Count) { & $add (New-HcHeading (T 'fix.heading').TrimEnd('?')) }
    for ($i = 0; $i -lt $actions.Count; $i++) {
        $a = $actions[$i]
        $fix = $script:Fixes[$a.FixId]
        $content = New-Object Windows.Controls.StackPanel
        [void]$content.Children.Add((New-HcText (T ('fix.' + $a.FixId) $a.Target.Label) 15 '' -Bold -Margin @(0, 0, 0, 0)))
        $note = T ('fix.note.' + $fix.Note)
        if ($fix.Admin -and -not $script:IsAdmin) { $note += ' ' + (T 'fix.needsAdmin') }
        $noteText = New-HcText $note 13 '' -Margin @(0, 1, 0, 0)
        $noteText.Opacity = 0.8
        [void]$content.Children.Add($noteText)
        $style = if ($i -eq 0) { 'HcPrimary' } else { 'HcButton' }
        $b = New-HcButton $content @{ Do = 'fix'; Index = $i } $style
        $b.IsEnabled = -not (Test-HcBusy)
        & $add $b
        if ($w.Confirm -eq $i) {
            $label = T ('fix.' + $a.FixId) $a.Target.Label
            $question = if ($fix.Admin -and -not $script:IsAdmin -and -not $script:DryRun) { T 'win.elevateAsk' } else { T 'win.confirm' $label }
            & $add (New-HcQuestion $question 'fixYes' 'fixNo' @{ Index = $i })
        }
    }
    if ($steps.Count) {
        & $add (New-HcButton (T 'fix.steps') @{ Do = 'steps' })
        if ($w.ShowSteps) {
            for ($i = 0; $i -lt $steps.Count; $i++) {
                & $add (New-HcText ((T 'fix.stepOf' ($i + 1) $steps.Count) + ' ' + $steps[$i]) 15 'Text' -Margin @(4, 2, 0, 8))
            }
        }
    }
}

function Add-HcCheckAllView {
    param($Panel)
    $w = $script:HcWin
    $all = $w.All
    $add = { param($element) [void]$Panel.Children.Add($element) }
    $total = $all.Codes.Count
    $done = $all.Done.Count
    if ((Test-HcBusy) -and -not $all.Stopped) {
        $next = if ($done -lt $total) { $all.Codes[$done] } else { '' }
        & $add (New-HcText (T 'win.checkAllOf' ([Math]::Min($done + 1, $total)) $total ($next + ' ' + (T "problem.$next"))) 15 'Soft')
        $bar = New-Object Windows.Controls.ProgressBar
        $bar.Minimum = 0
        $bar.Maximum = $total
        $bar.Value = $done
        $bar.Height = 6
        $bar.Margin = New-HcThickness @(0, 2, 0, 10)
        $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
        & $add $bar
        & $add (New-HcButton (T 'win.stop') @{ Do = 'stopAll' })
    } elseif ($all.Stopped) {
        & $add (New-HcText (T 'win.stopped' $done $total) 15 'Soft')
    } else {
        & $add (New-HcText (T 'win.checkAllDone') 15 'Soft')
    }
    # Problems first, then warnings, then the rest, each in menu order.
    $order = @{ problem = 0; warn = 1; ok = 2; error = 3 }
    $rows = @($all.Done | Sort-Object @{ Expression = { $order[$_.Level] } }, @{ Expression = { $_.Index } })
    foreach ($row in $rows) {
        $content = New-Object Windows.Controls.StackPanel
        $status = if ($row.Level -eq 'error') { 'skipped' } else { $row.Level }
        [void]$content.Children.Add((New-HcLine $status ($row.Code + '  ' + (T "problem.$($row.Code)"))))
        if ($row.Detail) {
            $detail = New-HcText $row.Detail 13 '' -Margin @(36, 0, 0, 0)
            $detail.Opacity = 0.8
            [void]$content.Children.Add($detail)
        }
        $b = New-HcButton $content @{ Do = 'allRow'; Code = $row.Code }
        $b.Padding = New-HcThickness @(10, 7, 10, 5)
        $b.Margin = New-HcThickness @(0, 0, 0, 6)
        $b.IsEnabled = [bool]$w.Reports[$row.Code]
        & $add $b
    }
}

function Update-HcOther {
    $w = $script:HcWin
    $panel = $w.Window.FindName('OtherPanel')
    $panel.Children.Clear()
    $add = { param($element) [void]$panel.Children.Add($element) }
    if ($w.Tab -eq 'problems') { return }
    if ($w.Tab -notin @('visit', 'start')) { & $add (New-HcText (T "win.tab.$($w.Tab)") 24 'Text' -Bold -Margin @(0, 0, 0, 12)) }
    switch ($w.Tab) {
        'start' { Update-HcStartPanel $panel }
        'safety' {
            & $add (New-HcText (T 'win.safetyIntro') 15 'Soft' -Margin @(0, 0, 0, 14))
            $wrap = New-Object Windows.Controls.WrapPanel
            foreach ($code in @('F2', 'F1', 'F3')) {
                $card = New-Object Windows.Controls.StackPanel
                $card.Width = 260
                [void]$card.Children.Add((New-HcText (T "problem.$code") 17 'Text' -Bold))
                [void]$card.Children.Add((New-HcText (T "win.safety.$code") 14 'Soft' -Margin @(0, 0, 0, 12)))
                $style = if ($code -eq 'F3') { 'HcPrimary' } else { 'HcButton' }
                [void]$card.Children.Add((New-HcButton ((T 'win.check') + " ($code)") @{ Do = 'problem'; Code = $code } $style))
                $box = New-HcBox '' @($card) 'Panel'
                $box.Margin = New-HcThickness @(0, 0, 14, 14)
                $box.Padding = New-HcThickness @(16, 14, 16, 8)
                [void]$wrap.Children.Add($box)
            }
            & $add $wrap
        }
        'visit' { Update-HcHistoryPanel $panel }
        'pc' { Update-HcPcPanel $panel }
        'ai' { Update-HcAiPanel $panel }
    }
}

# ---------------------------------------------------------------- doing --

function Invoke-HcClick {
    param($Sender)
    $w = $script:HcWin
    try {
        $tag = $Sender.Tag
        switch ($tag.Do) {
            'tab'      {
                if ($tag.Tab -eq 'visit') { Open-HcVisitTab $w.VisitView; return }
                # Problemen and the phone tab share the result column's state:
                # a result from the other one is not shown here.
                $phoneCode = $w.Code -like 'M*'
                if (($tag.Tab -eq 'phone' -and -not $phoneCode) -or ($tag.Tab -eq 'problems' -and $phoneCode)) {
                    if (-not (Test-HcBusy)) { $w.Code = $null; $w.Report = $null; $w.View = 'empty'; Clear-HcMessages }
                }
                $w.Tab = $tag.Tab; Update-HcTabs; Update-HcOther
                if ($w.Tab -in @('phone', 'problems')) { Update-HcResult }
                if ($w.Tab -eq 'phone') { Update-HcPhone }
            }
            'language' { $script:Lang = if ($script:Lang -eq 'nl') { 'en' } else { 'nl' }; Update-HcAll }
            'theme'    { Set-HcTheme $(if ($w.Theme -eq 'dark') { 'light' } else { 'dark' }); Update-HcStatus }
            'area'     { $w.Open[$tag.Letter] = -not $w.Open[$tag.Letter]; Update-HcGroups }
            'problem'  { Open-HcProblem $tag.Code }
            'input'    { Submit-HcInput }
            'checkAll' { Start-HcCheckAll }
            'stopAll'  { $w.Queue.Clear(); $w.All.Stopped = $true; Update-HcResult }
            'allRow'   {
                $w.Code = $tag.Code
                $w.Report = $w.Reports[$tag.Code]
                $w.Input = $w.Inputs[$tag.Code]
                $w.FromAll = $true
                Clear-HcMessages
                $w.View = 'report'
                $script:HcCurrentCode = $tag.Code
                Save-HcVisit $tag.Code $w.Report
                Update-HcResult
            }
            'backToAll' { $w.View = 'checkall'; $w.FromAll = $false; Clear-HcMessages; Update-HcResult; Update-HcGroups }
            'steps'    { $w.ShowSteps = -not $w.ShowSteps; Update-HcResult }
            'fix'      { $w.Confirm = $tag.Index; $w.Notice = $null; Update-HcResult }
            'fixNo'    { $w.Confirm = $null; $w.Notice = T 'fix.cancelled'; Update-HcResult }
            'fixYes'   { $w.Confirm = $null; Invoke-HcWindowFix $tag.Index }
            'undo'     {
                $w.UndoAsk = @($script:HcChanges | Where-Object { $script:Fixes[$_.FixId].Undo }).Count
                if (-not $w.UndoAsk) { $w.UndoAsk = $null; $w.Notice = T 'undo.nothing' }
                $w.Tab = 'problems'; Update-HcTabs; Update-HcResult
            }
            'undoNo'   { $w.UndoAsk = $null; $w.Notice = T 'fix.cancelled'; Update-HcResult }
            'changes'  {
                if (Test-HcBusy) { return }
                Clear-HcMessages
                $w.View = 'changes'; $w.FromAll = $false
                if ($w.Tab -ne 'problems') { $w.Tab = 'problems'; Update-HcTabs }
                Update-HcResult
            }
            'changeAsk' { $w.ChangeAsk = @{ Index = $tag.Index; Kind = $tag.Kind }; $w.Banner = $null; $w.Notice = $null; Update-HcResult }
            'changeNo'  { $w.ChangeAsk = $null; $w.Notice = T 'fix.cancelled'; Update-HcResult }
            'changeYes' { Start-HcChangeStep }
            'undoYes'  { $w.UndoAsk = $null; Start-HcWindowUndo }
            'close'    {
                if (Test-HcBusy) { return }
                $w.Outcome = $tag.Outcome
                $w.Window.Close()
            }
            default    { if (-not (Invoke-HcPcClick $tag) -and -not (Invoke-HcPhoneClick $tag) -and -not (Invoke-HcAiClick $tag)) { Invoke-HcVisitClick $tag } }
        }
    } catch {
        $w.Notice = T 'win.error' $_.Exception.Message
        Update-HcResult
    }
}

function Clear-HcMessages {
    $w = $script:HcWin
    $w.Banner = $null
    $w.Notice = $null
    $w.Confirm = $null
    $w.ShowSteps = $false
    $w.UndoAsk = $null
    $w.ChangeAsk = $null
}

function Open-HcProblem {
    param([string]$Code)
    $w = $script:HcWin
    if (Test-HcBusy) { return }
    # A phone check opens in the phone tab, on the chosen device; M8 is its
    # connect view there.
    if ($Code -like 'M*') {
        $w.Tab = 'phone'
        $w.FromAll = $false
        Clear-HcMessages
        Update-HcTabs
        if ($Code -eq 'M8' -or -not $w.Ph.Serial) {
            $w.Ph.Connect = $true
            $w.Code = $null; $w.View = 'empty'
            Update-HcResult
            Update-HcPhone
            return
        }
        $w.Code = $Code
        Update-HcPhone
        Start-HcWindowCheck $Code $w.Ph.Serial
        return
    }
    $w.Tab = 'problems'
    $w.Code = $Code
    $w.FromAll = $false
    Clear-HcMessages
    Update-HcTabs
    if ($Code -in @('A3', 'A4', 'M8')) {
        $w.Input = $w.Inputs[$Code]
        $w.View = 'input'
        Update-HcGroups
        Update-HcResult
        return
    }
    Start-HcWindowCheck $Code $null
}

# A3, A4 and M8 need an address first; checked the same way the text menu does.
function Submit-HcInput {
    $w = $script:HcWin
    $typed = "$($w.InputBox.Text)".Trim()
    $w.Input = $typed
    if (-not $typed) { return }
    if ($w.Code -eq 'A3') {
        if (-not (ConvertTo-HcHostName $typed)) { $w.Notice = T 'site.invalid' $typed; Update-HcResult; return }
    } elseif ($w.Code -eq 'M8') {
        if (-not (ConvertFrom-HcPairInput $typed)) { $w.Notice = T 'pair.invalid' $typed; Update-HcResult; return }
    } elseif (-not (ConvertTo-HcMailDomain $typed)) {
        $w.Notice = T 'mail.invalid' $typed; Update-HcResult; return
    }
    $w.Inputs[$w.Code] = $typed
    $w.Notice = $null
    Start-HcWindowCheck $w.Code $typed
}

function Start-HcWindowCheck {
    param([string]$Code, [string]$Text, [string]$Banner, [string]$BusyText = (T 'run.checking'))
    $w = $script:HcWin
    $w.View = 'busy'
    $w.BusyText = $BusyText
    Add-HcJob @{ Kind = 'check'; Code = $Code; Text = $Text; Banner = $Banner; Done = 'Complete-HcWindowCheck' }
    Update-HcGroups
    Update-HcResult
}

function Get-HcJobReport {
    param([object[]]$Output)
    @($Output | Where-Object { $_ -and $_.PSObject.Properties['FindingId'] -and $_.PSObject.Properties['Results'] }) | Select-Object -Last 1
}

function Complete-HcWindowCheck {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $report = Get-HcJobReport $Output
    if ($ErrorText -or -not $report) {
        $w.View = 'empty'
        $w.Notice = T 'win.error' $(if ($ErrorText) { $ErrorText } else { '-' })
        Update-HcResult
        return
    }
    $w.Report = $report
    $w.Reports[$Job.Code] = $report
    $w.Inputs[$Job.Code] = $Job.Text
    $w.Banner = $Job.Banner
    $w.View = 'report'
    $script:HcCurrentCode = $Job.Code
    Save-HcVisit $Job.Code $report
    Update-HcGroups
    Update-HcResult
    $w.Window.FindName($(if ($w.Tab -eq 'phone') { 'PhoneResultScroll' } else { 'ResultScroll' })).ScrollToTop()
    if ($Job.Code -like 'M*') {
        # Paired over Wi-Fi: read the devices again, with that one chosen.
        if ($Job.Code -eq 'M8' -and @($report.Results | Where-Object { $_.Text -eq (T 'and.wifiConnected') }).Count) {
            $w.Ph.Connect = $false
            $w.Ph.PreferWifi = $true
            Start-HcPhoneLoad
        }
        Update-HcPhone
    }
}

function Start-HcCheckAll {
    $w = $script:HcWin
    if (Test-HcBusy) { return }
    $codes = Get-HcCheckAllCodes
    $w.All = @{ Codes = $codes; Done = New-Object System.Collections.ArrayList; Stopped = $false }
    $w.Tab = 'problems'
    $w.Code = $null
    $w.FromAll = $false
    $w.View = 'checkall'
    Clear-HcMessages
    for ($i = 0; $i -lt $codes.Count; $i++) {
        Add-HcJob @{ Kind = 'check'; Code = $codes[$i]; Index = $i; Done = 'Complete-HcCheckAllItem' }
    }
    Update-HcTabs
    Update-HcGroups
    Update-HcResult
}

# One check of "Alles controleren" is back. Only what is not all right goes
# on the note; a clean result would only make it longer.
function Complete-HcCheckAllItem {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $report = Get-HcJobReport $Output
    $row = [pscustomobject]@{ Code = $Job.Code; Index = $Job.Index; Level = 'error'; Detail = $ErrorText }
    if ($report -and -not $ErrorText) {
        $w.Reports[$Job.Code] = $report
        $row.Level = Get-HcReportLevel $report
        $row.Detail = @($report.Results | Where-Object { $_.Status -eq $row.Level } | ForEach-Object { $_.Text }) | Select-Object -First 1
        if ($row.Level -ne 'ok') { Save-HcVisit $Job.Code $report }
    }
    [void]$w.All.Done.Add($row)
    if ($w.View -eq 'checkall') { Update-HcResult }
    # The dot on the problem, at once.
    Update-HcGroups
}

# A fix, picked and confirmed: the same order of things as the text menu
# (Invoke-HcActionMenu), with the window's own question instead of J/N.
function Invoke-HcWindowFix {
    param([int]$Index)
    $w = $script:HcWin
    $action = @($w.Report.Actions)[$Index]
    $fix = $script:Fixes[$action.FixId]
    $label = T ('fix.' + $action.FixId) $action.Target.Label
    $w.Banner = $null

    if ($fix.Admin -and -not $script:IsAdmin -and -not $script:DryRun) {
        if (-not $script:HcSource) { $w.Notice = T 'fix.adminHow'; Update-HcResult; return }
        if (Start-HcElevated $script:HcCurrentCode) {
            $script:HandedOff = $true
            $w.Outcome = 'handedoff'
            $w.Window.Close()
            return
        }
        $w.Notice = T 'fix.cancelled'
        Update-HcResult
        return
    }
    if ($script:DryRun) { $w.Notice = T 'fix.dryRun'; Update-HcResult; return }

    $w.View = 'busy'
    $w.BusyText = $label + '...'
    Add-HcJob @{ Kind = 'fix'; FixId = $action.FixId; Target = $action.Target; Code = $w.Code; Text = $w.Inputs[$w.Code]; Done = 'Complete-HcWindowFix' }
    Update-HcSide
    Update-HcResult
}

function Complete-HcWindowFix {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    if ($ErrorText) {
        $w.View = 'report'
        $w.Notice = T 'fix.failed' $ErrorText
        Update-HcResult
        return
    }
    $fix = $script:Fixes[$Job.FixId]
    $done = T ('fix.' + $Job.FixId + '.done') $Job.Target.Label
    if (-not $fix.NoLog) {
        [void](Add-HcChange $Job.FixId $Job.Target $done)
    }
    # A fix often brings the internet back: measure again, for the pill,
    # the invoice and the history.
    if (-not $w.Environment.Online) { Add-HcJob @{ Kind = 'online'; Done = 'Complete-HcOnline' } }
    $banner = T 'win.doneAgain' $done
    if ($Info.Count) { $banner = ($Info -join ' ') + ' ' + $banner }
    Start-HcWindowCheck $Job.Code $Job.Text $banner (T 'fix.checkingAgain')
    Update-HcSide
}

function Complete-HcOnline {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    if (-not $ErrorText -and @($Output) -contains $true) {
        $w.Environment.Online = $true
        Update-HcSide
    }
}

# U in the window: this visit's changes undone, newest first, then the
# problem on screen checked again so the result shows it.
function Start-HcWindowUndo {
    $w = $script:HcWin
    $undoable = @($script:HcChanges | Where-Object { $script:Fixes[$_.FixId].Undo })
    $w.UndoMessages = New-Object System.Collections.ArrayList
    for ($i = $undoable.Count - 1; $i -ge 0; $i--) {
        $change = $undoable[$i]
        Add-HcJob @{ Kind = 'undo'; FixId = $change.FixId; Target = $change.Target; Change = $change; Last = ($i -eq 0); Done = 'Complete-HcWindowUndo' }
    }
    # From the history: stay there, so each change shows it is undone.
    $w.UndoInChanges = $w.View -eq 'changes'
    if ($w.UndoInChanges) { $w.Banner = T 'menu.undo' }
    else { $w.View = if ($w.Report) { 'busy' } else { 'empty' } }
    $w.BusyText = T 'menu.undo'
    Update-HcSide
    Update-HcResult
}

function Complete-HcWindowUndo {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    if ($ErrorText) {
        [void]$w.UndoMessages.Add((T 'undo.failed' $Job.Change.Label))
    } else {
        Set-HcChangeUndone $Job.Change
        [void]$w.UndoMessages.Add((T 'undo.done' $Job.Change.Label))
    }
    if (-not $Job.Last) { if ($w.UndoInChanges) { Update-HcResult }; return }
    $message = @($w.UndoMessages) -join ' / '
    if ($w.UndoInChanges) {
        $w.UndoInChanges = $false
        $w.View = 'changes'
        $w.Banner = $message
        Update-HcResult
    } elseif ($w.Code -and $w.Report) {
        Start-HcWindowCheck $w.Code $w.Inputs[$w.Code] $message (T 'fix.checkingAgain')
    } else {
        $w.View = 'empty'
        $w.Banner = $message
        Update-HcResult
    }
    Update-HcSide
}

# ------------------------------------------------------------------ main --

function Show-HcWindow {
    param([pscustomobject]$Environment, [string]$Start, [string]$Message)
    if (-not (Test-HcWindowPossible)) { return 'failed' }
    try {
        $window = [Windows.Markup.XamlReader]::Parse((New-HcWindowXaml))
    } catch {
        Write-Warn2 (T 'win.failed' $_.Exception.Message)
        return 'failed'
    }

    $open = @{}
    foreach ($letter in $script:Areas.Keys) { $open[$letter] = $true }
    $script:HcWin = @{
        Window = $window; Environment = $Environment; Tab = 'start'; Theme = 'light'; Open = $open
        View = 'empty'; Code = $null; Report = $null; Reports = @{}; Inputs = @{}; Input = $null; InputBox = $null
        Banner = $null; Notice = $Message; Confirm = $null; ShowSteps = $false; UndoAsk = $null; UndoMessages = $null
        FromAll = $false; All = $null; BusyText = ''; Clock = $null; SearchFirst = $null; ChangeAsk = $null; UndoInChanges = $false
        Queue = New-Object System.Collections.ArrayList; Job = $null; WasBusy = $false
        Runspace = $null; Outcome = 'done'; Finished = $false; CloseAnyway = $false; CloseAsk = $false
        VisitView = 'finish'; Fin = (New-HcFinishState); Hist = @{ Stage = 'new'; Visits = @(); Confirm = $null; Notice = $null }
        Pc = @{ Stage = 'new'; Facts = $null; Advice = @(); Error = $null }; Ai = (New-HcAiState); Ph = (New-HcPhoneState)
        Totp = $null; PcId = $null; PreviewDue = $null; WorkBox = $null; ExtraText = $null; ExtraPrice = $null
    }
    $w = $script:HcWin
    try { $window.Icon = New-HcLogoImage } catch { }

    # The window must fit an old 1366x768 laptop as well as a big screen.
    $area = [Windows.SystemParameters]::WorkArea
    $window.Width = [Math]::Min(1180, $area.Width * 0.96)
    $window.Height = [Math]::Min(800, $area.Height * 0.94)

    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'STA'
    $rs.ThreadOptions = 'ReuseThread'
    $rs.Open()
    $w.Runspace = $rs
    Add-HcJob @{ Kind = 'load'; Source = $script:HcSource; Start = $Start; Done = 'Complete-HcLoad' }

    Set-HcTheme (Get-HcDefaultTheme)
    # The search box above the problems: the list follows every key; Enter
    # opens the best match, Esc empties it, Ctrl+F jumps to it.
    $search = $window.FindName('ProblemSearch')
    $search.Add_TextChanged({ try { Update-HcGroups } catch { } })
    $search.Add_KeyDown({
        if ($_.Key -eq 'Return' -and $script:HcWin.SearchFirst) { $_.Handled = $true; Open-HcProblem $script:HcWin.SearchFirst }
        elseif ($_.Key -eq 'Escape') { $_.Handled = $true; $this.Text = '' }
    })
    $window.Add_PreviewKeyDown({
        if ($_.Key -eq 'F' -and [Windows.Input.Keyboard]::Modifiers -eq 'Control') {
            $_.Handled = $true
            $w = $script:HcWin
            if ($w.Tab -ne 'problems') { $w.Tab = 'problems'; Update-HcTabs; Update-HcResult }
            $box = $w.Window.FindName('ProblemSearch')
            [void]$box.Focus()
            $box.SelectAll()
        }
    })
    Update-HcAll

    $timer = New-Object Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(120)
    $timer.Add_Tick({ Invoke-HcTick })
    $clock = New-Object Windows.Threading.DispatcherTimer
    $clock.Interval = [TimeSpan]::FromSeconds(20)
    $clock.Add_Tick({ try { Update-HcClock } catch { } })

    # A fix or undo halfway must finish: closing waits for it. And a visit
    # ends with a document: closing first goes to Afronden, once.
    $window.Add_Closing({
        $w = $script:HcWin
        try {
            $job = $w.Job
            if ($job -and $job.Kind -in @('fix', 'undo')) {
                $_.Cancel = $true
                $w.Notice = T 'win.busyClose'
                Update-HcResult
                return
            }
            $worth = $script:HcVisit.Count -gt 0 -or $script:HcChanges.Count -gt 0
            if ($worth -and -not $w.Finished -and -not $w.CloseAnyway -and $w.Outcome -notin @('console', 'handedoff')) {
                $_.Cancel = $true
                $w.CloseAsk = $true
                Open-HcVisitTab 'finish'
            }
        } catch { }
    })
    $window.Add_ContentRendered({ $this.Topmost = $true; $this.Activate(); $this.Topmost = $false })
    $window.Add_SizeChanged({ try { Update-HcZoom } catch { } })

    $timer.Start()
    $clock.Start()
    try {
        [void]$window.ShowDialog()
    } finally {
        $timer.Stop()
        $clock.Stop()
        if ($w.Job) { try { [void]$w.Job.PS.BeginStop($null, $null) } catch { } }
        try { $rs.CloseAsync() } catch { }
    }
    $w.Outcome
}

<#
    Pure: how much bigger everything is drawn. The window is laid out for an
    old 1280x800 laptop; on a bigger screen, or maximised, it grows with the
    window (by the side that runs out first) instead of staying small in
    the top left corner, up to 30% (Shamil's maximised screen, 6 Oct).
#>
function Get-HcZoom {
    param([double]$Width, [double]$Height)
    if ($Width -le 0 -or $Height -le 0) { return 1.0 }
    [Math]::Round([Math]::Max(1.0, [Math]::Min(1.3, [Math]::Min($Width / 1280, $Height / 800))), 3)
}

function Update-HcZoom {
    $window = $script:HcWin.Window
    $zoom = Get-HcZoom $window.ActualWidth $window.ActualHeight
    $root = $window.Content
    $now = if ($root.LayoutTransform -is [Windows.Media.ScaleTransform]) { $root.LayoutTransform.ScaleX } else { 1.0 }
    if ([Math]::Abs($now - $zoom) -lt 0.01) { return }
    $root.LayoutTransform = New-Object Windows.Media.ScaleTransform($zoom, $zoom)
}

function Complete-HcLoad {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    if ($ErrorText) {
        $w.Notice = T 'win.error' $ErrorText
        Update-HcResult
        return
    }
    # The PC's scrambled id, for the relay, read once while nothing else runs.
    Add-HcJob @{ Kind = 'pcid'; Done = 'Complete-HcPcId' }
    if ($Job.Start -and ($script:Areas.Values | ForEach-Object { $_ }) -contains $Job.Start) { Open-HcProblem $Job.Start }
}

function Complete-HcPcId {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $id = @($Output | Where-Object { "$_" -match '^[0-9a-f]{64}$' }) | Select-Object -First 1
    if ($id) { $script:HcWin.PcId = [string]$id }
}

# The logo as the window's icon: the white house with its orange waves on
# a navy tile, the same mark as the business card.
function New-HcLogoImage {
    $white = [Windows.Media.Brushes]::White
    $orange = New-Object Windows.Media.SolidColorBrush([Windows.Media.Color]::FromRgb(0xE8, 0x86, 0x2E))
    $navy = New-Object Windows.Media.SolidColorBrush([Windows.Media.Color]::FromRgb(0x16, 0x32, 0x3F))
    $pen = { param($brush, $width)
        $p = New-Object Windows.Media.Pen($brush, $width)
        $p.StartLineCap = 'Round'; $p.EndLineCap = 'Round'; $p.LineJoin = 'Round'
        $p }
    $mark = New-Object Windows.Media.DrawingGroup
    foreach ($d in @('M6,33 L28,14 L50,33', 'M13,31 V54 A3,3 0 0 0 16,57 H40 A3,3 0 0 0 43,54 V31')) {
        [void]$mark.Children.Add((New-Object Windows.Media.GeometryDrawing($null, (& $pen $white 6), [Windows.Media.Geometry]::Parse($d))))
    }
    [void]$mark.Children.Add((New-Object Windows.Media.GeometryDrawing($white, $null, (New-Object Windows.Media.RectangleGeometry((New-Object Windows.Rect(23, 41, 10, 16)), 2, 2)))))
    foreach ($d in @('M46,16 A8,8 0 0 1 52,22', 'M47,7.5 A16,16 0 0 1 60.5,21')) {
        [void]$mark.Children.Add((New-Object Windows.Media.GeometryDrawing($null, (& $pen $orange 4.5), [Windows.Media.Geometry]::Parse($d))))
    }
    $mark.Transform = New-Object Windows.Media.ScaleTransform(0.78, 0.78, 33, 33)
    $all = New-Object Windows.Media.DrawingGroup
    [void]$all.Children.Add((New-Object Windows.Media.GeometryDrawing($navy, $null, (New-Object Windows.Media.RectangleGeometry((New-Object Windows.Rect(0, 0, 64, 64)), 14, 14)))))
    [void]$all.Children.Add($mark)
    $image = New-Object Windows.Media.DrawingImage($all)
    $image.Freeze()
    $image
}

# ==================================================== src\window-visit.ps1 ==
<#
    The window's Bezoek tab (phase 6, step 2): finishing the visit with an
    invoice or a plain note, and this PC's earlier visits.

    Both start with the Authenticator code, in six slots: the prices, the
    invoice number and the history all live behind the relay. With the code
    in, the form fills a live A4 preview (the same page that is printed),
    and "Factuur maken" needs nothing more. A note needs no code at all.

    The form writes straight into the visit's own state ($script:HcAsked,
    $script:HcWork), so the invoice, the note and the history get exactly
    what the text menu would give them. Relay calls run in the worker.
#>

# ------------------------------------------------------------ pure parts --

# The lines of the invoice being filled in: time, call-out, and the extra
# parts that were added with a valid amount.
function Get-HcDraftLines {
    param([hashtable]$Fin, $Settings)
    foreach ($l in @(Get-HcLabourLines ([int]$Fin.Minutes) $Settings)) { $l }
    $fee = [decimal]$(if ($Settings.callout_fee) { $Settings.callout_fee } else { 0 })
    if ($Fin.Callout -and $fee -gt 0) { [pscustomobject]@{ Description = (T 'inv.calloutLine'); Amount = $fee } }
    foreach ($e in @($Fin.Extras)) { [pscustomobject]@{ Description = $e.Description; Amount = [decimal]$e.Amount } }
}

# The invoice as it will look before the relay numbers it: the same shape
# invoice_create returns, so one page layout draws both.
function New-HcDraftInvoice {
    param([hashtable]$Fin, $Settings, [datetime]$Now = (Get-Date))
    $lines = @(Get-HcDraftLines $Fin $Settings)
    $total = [decimal]0
    foreach ($l in $lines) { $total += [decimal]$l.Amount }
    $subtotal = $total
    $btw = [decimal]0
    if ("$($Settings.btw_mode)" -eq '21') {
        $subtotal = [Math]::Round($total / [decimal]1.21, 2)
        $btw = $total - $subtotal
    }
    $days = if ($Settings.payment_days) { [int]$Settings.payment_days } else { 14 }
    [pscustomobject]@{
        number               = (T 'win.fin.draft')
        issued_at            = $Now.ToUniversalTime().ToString('o')
        seller               = $(if ($Settings) { $Settings } else { [pscustomobject]@{ business_name = 'Housecall' } })
        client_name          = Format-HcClientName $Fin.Title $Fin.Name
        client_address       = "$($Fin.Address)".Trim()
        client_postcode_city = "$($Fin.Postcode)".Trim()
        client_email         = "$($Fin.Email)".Trim()
        lines                = @($lines | ForEach-Object { [pscustomobject]@{ description = $_.Description; amount = [decimal]$_.Amount } })
        btw_mode             = "$($Settings.btw_mode)"
        subtotal             = $subtotal
        btw_amount           = $btw
        total                = $total
        payment              = $Fin.Payment
        due_date             = $Now.AddDays($days).ToString('yyyy-MM-dd')
    }
}

# The salutations a client can get, in the order they are offered. Dutch
# has one word for a woman, married or not (Mevr.); English tells Mrs.
# (married) from Ms. (not married, or not known), so Ms. is English only.
$script:HcTitles = @('none', 'mr', 'mrs', 'ms', 'couple', 'family')

function Get-HcTitleChoices {
    param([string]$Lang = $script:Lang)
    @($script:HcTitles | Where-Object { $Lang -ne 'nl' -or $_ -ne 'ms' })
}

# "Mevr. Anna de Vries", "Mr. and Mrs. Smith", "The Smith family": the name as
# it goes on the note, the invoice and in the history.
function Format-HcClientName {
    param([string]$Title, [string]$Name, [string]$Lang = $script:Lang)
    $n = "$Name".Trim()
    if (-not $n -or -not $Title -or $Title -eq 'none') { return $n }
    $format = $script:Strings[$Lang]["name.$Title"]
    if (-not $format) { return $n }
    $format -f $n
}

# The other way round, for a name from the history: "Mevr. de Vries" gives
# mrs and "de Vries", in either language; anything else stays as it is.
function Split-HcClientName {
    param([string]$Label)
    $text = "$Label".Trim()
    foreach ($lang in @('nl', 'en')) {
        foreach ($title in @('couple', 'family', 'mr', 'mrs', 'ms')) {
            $format = $script:Strings[$lang]["name.$title"]
            if (-not $format) { continue }
            $pattern = '^' + ([regex]::Escape($format) -replace '\\\{0\}', '(.+)') + '$'
            if ($text -match $pattern) { return [pscustomobject]@{ Title = $title; Name = $Matches[1].Trim() } }
        }
    }
    [pscustomobject]@{ Title = 'none'; Name = $text }
}

# The mail that goes with the PDF, in the visit's language: the greeting by
# salutation, one sentence on what is attached, and Shamil's name (and
# phone, once it is in his settings) under it. Kind is invoice, receipt or note.
function New-HcMailText {
    param([string]$Kind, [string]$Title, [string]$Name, [datetime]$Date, [string]$Number, $Settings)
    $n = "$Name".Trim()
    $greet = if (-not $n) { T 'mail.greet.anon' } else { T "mail.greet.$(if ($Title) { $Title } else { 'none' })" $n }
    $subject = if ($Kind -eq 'invoice') { T 'mail.subject.invoice' $Number } else { T "mail.subject.$Kind" }
    $sign = @((T 'mail.regards'), $(if ($Settings.business_name) { [string]$Settings.business_name } else { 'Housecall' }), (T 'mail.brand'))
    if ($Settings.phone) { $sign += [string]$Settings.phone }
    $text = @($greet, '', (T "mail.body.$Kind" (Format-HcLongDate $Date)), '', (T 'mail.questions'), '', ($sign -join "`n")) -join "`n"
    [pscustomobject]@{ Subject = $subject; Text = $text }
}

# How the client can pay: a transfer only once an IBAN is set, since the
# invoice has to say where to.
function Get-HcPayMethods {
    # -Receipt: a betaalbewijs says "voldaan", so paying later is not one of them.
    param($Settings, [switch]$Receipt)
    $methods = @('pin', 'cash', 'tikkie')
    if ($Settings.iban -and -not $Receipt) { $methods += 'transfer' }
    $methods
}

# The start of a visit's state in the window.
function New-HcFinishState {
    @{
        Stage = 'new'; Mode = 'invoice'; Settings = $null; Notice = $null; Invoice = $null; Saved = $false; Pages = $null
        Title = (Split-HcClientName $script:HcKnownLabel).Title; Name = (Split-HcClientName $script:HcKnownLabel).Name; Address = ''; Postcode = ''; Email = ''; Minutes = 0; Callout = $true
        Extras = New-Object System.Collections.ArrayList; Payment = 'pin'; Offline = $false; CalcBlock = $null; AllPresets = $false
        MailAsk = $null; MailBusy = $false; MailResult = $null
        # The kept PDF: one id per visit, so a second save replaces the first.
        DocId = [guid]::NewGuid().ToString(); VisitId = $null; DocSaved = $false; DocFailed = $false
    }
}

# ------------------------------------------------------------- opening --

function Open-HcVisitTab {
    param([string]$View = 'finish')
    $w = $script:HcWin
    $w.Tab = 'visit'
    $w.VisitView = $View
    if ($View -eq 'finish') { Start-HcFinish } else { Start-HcHistory }
    Update-HcTabs
    Update-HcVisit
}

function Start-HcFinish {
    $w = $script:HcWin
    $f = $w.Fin
    if ($f.Stage -ne 'new') { return }
    if (-not $f.Minutes) { $f.Minutes = Get-HcSuggestedMinutes }
    # Without the relay there is no invoice; the note is always possible.
    if (-not $w.Environment.Online -or $script:DryRun) {
        $f.Mode = 'note'
        $f.Stage = 'form'
        $f.Offline = $true
        return
    }
    if (Test-HcUnlocked) { Start-HcSettingsLoad } else { $f.Stage = 'code' }
}

function Start-HcSettingsLoad {
    $f = $script:HcWin.Fin
    $f.Stage = 'loading'
    Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'settings_get'; token = $script:HcToken }; Done = 'Complete-HcSettings' }
}

function Get-HcRelayResult {
    param([object[]]$Output)
    @($Output | Where-Object { $_ -and $_.PSObject.Properties['Ok'] }) | Select-Object -Last 1
}

function Complete-HcSettings {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $f = $script:HcWin.Fin
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) {
        $code = if ($r) { $r.Error } else { 'unreachable' }
        if ($code -eq 'locked_out') { $script:HcToken = $null; $f.Stage = 'code'; $f.Notice = T 'relay.expired' }
        else { $f.Stage = 'form'; $f.Mode = 'note'; $f.Notice = T 'inv.failed' (Get-HcRelayMessage $code) }
        Update-HcVisit
        return
    }
    $s = $r.Data.settings
    if ($s) { Set-HcContact $s }
    if (-not $s -or -not $s.business_name) {
        $f.Stage = 'form'; $f.Mode = 'note'; $f.Notice = T 'inv.noSettings'
        Update-HcVisit
        return
    }
    $f.Settings = $s
    $script:HcStartMinutes = if ([decimal]$(if ($s.start_fee) { $s.start_fee } else { 0 }) -gt 0) { [int]$s.start_minutes } else { 0 }
    if ((Get-HcPayMethods $s) -notcontains $f.Payment) { $f.Payment = 'pin' }
    $f.Stage = 'form'
    Update-HcVisit
    Update-HcClock
}

# ----------------------------------------------------------- code slots --

# Six boxes for the Authenticator code. Typing moves on by itself, pasting
# fills them all, Backspace goes back, and Enter (or the sixth digit) sends.
# -For 'pair' is the Wi-Fi pairing code of the phone tab: the same boxes,
# with its own label, hint and button.
function New-HcCodeBox {
    param([string]$For, [string]$Intro, [string]$Label = (T 'win.code.label'), [string]$Hint = (T 'win.code.hint'), [string]$GoText = (T 'win.code.go'))
    $w = $script:HcWin
    $w.Totp = @{ For = $For; Slots = @(); Hint = $null; Filling = $false }
    $stack = New-Object Windows.Controls.StackPanel
    if ($Intro) { [void]$stack.Children.Add((New-HcText $Intro 15 'Text' -Margin @(0, 0, 0, 10))) }
    [void]$stack.Children.Add((New-HcText $Label.ToUpperInvariant() 12 'Soft' -Bold -Margin @(0, 0, 0, 6)))
    $row = New-Object Windows.Controls.StackPanel
    $row.Orientation = 'Horizontal'
    $slots = @()
    for ($i = 0; $i -lt 6; $i++) {
        $box = New-Object Windows.Controls.TextBox
        $box.Width = 50
        $box.Height = 60
        $box.FontSize = 28
        $box.FontWeight = [Windows.FontWeights]::Bold
        $box.FontFamily = New-Object Windows.Media.FontFamily('Consolas')
        $box.TextAlignment = 'Center'
        $box.VerticalContentAlignment = 'Center'
        $box.MaxLength = 6
        $box.BorderThickness = New-HcThickness @(2, 2, 2, 2)
        $box.Margin = New-HcThickness @(0, 0, $(if ($i -eq 2) { 18 } else { 8 }), 0)
        $box.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'Panel')
        $box.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Text')
        $box.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Line')
        $box.SetResourceReference([Windows.Controls.TextBox]::CaretBrushProperty, 'Hi')
        $box.Tag = @{ Slot = $i }
        [Windows.Automation.AutomationProperties]::SetName($box, (T 'win.code.digit' ($i + 1)))
        $box.Add_PreviewTextInput({ if ($_.Text -notmatch '^\d+$') { $_.Handled = $true } })
        $box.Add_TextChanged({ Invoke-HcSlotChanged $this })
        $box.Add_PreviewKeyDown({ Invoke-HcSlotKey $this $_ })
        $box.Add_GotKeyboardFocus({
            $this.SelectAll()
            $this.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Hi')
        })
        $box.Add_LostKeyboardFocus({ $this.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Line') })
        if ($i -eq 0) { $box.Add_Loaded({ [void]$this.Focus() }) }
        $slots += $box
        [void]$row.Children.Add($box)
    }
    $w.Totp.Slots = $slots
    [void]$stack.Children.Add($row)
    $go = New-HcButton $GoText @{ Do = 'codeSubmit' } 'HcPrimary'
    $go.HorizontalAlignment = 'Left'
    $go.Margin = New-HcThickness @(0, 12, 0, 6)
    [void]$stack.Children.Add($go)
    $w.Totp.Hint = New-HcText $Hint 13.5 'Soft' -Margin @(0, 0, 0, 0)
    [void]$stack.Children.Add($w.Totp.Hint)
    New-HcBox '' @($stack) 'Side'
}

function Invoke-HcSlotChanged {
    param($Sender)
    $c = $script:HcWin.Totp
    if (-not $c -or $c.Filling) { return }
    try {
        $c.Filling = $true
        $i = $Sender.Tag.Slot
        $digits = $Sender.Text -replace '\D', ''
        if (-not $digits) { $Sender.Text = ''; return }
        # One digit, or a pasted code: spread it over this box and the next.
        for ($k = 0; $k -lt $digits.Length -and ($i + $k) -lt 6; $k++) { $c.Slots[$i + $k].Text = [string]$digits[$k] }
        [void]$c.Slots[[Math]::Min($i + $digits.Length, 5)].Focus()
    } finally {
        $c.Filling = $false
    }
    if ((($c.Slots | ForEach-Object { $_.Text }) -join '') -match '^\d{6}$') { Submit-HcCode }
}

function Invoke-HcSlotKey {
    param($Sender, $KeyArgs)
    $c = $script:HcWin.Totp
    $i = $Sender.Tag.Slot
    switch ([string]$KeyArgs.Key) {
        'Back' {
            if (-not $Sender.Text -and $i -gt 0) {
                $c.Slots[$i - 1].Text = ''
                [void]$c.Slots[$i - 1].Focus()
                $KeyArgs.Handled = $true
            }
        }
        'Left'   { if ($i -gt 0) { [void]$c.Slots[$i - 1].Focus(); $KeyArgs.Handled = $true } }
        'Right'  { if ($i -lt 5) { [void]$c.Slots[$i + 1].Focus(); $KeyArgs.Handled = $true } }
        'Return' { $KeyArgs.Handled = $true; Submit-HcCode }
    }
}

function Submit-HcCode {
    $w = $script:HcWin
    $c = $w.Totp
    if (-not $c -or (Test-HcBusy)) { return }
    $code = ($c.Slots | ForEach-Object { $_.Text }) -join ''
    if ($code -notmatch '^\d{6}$') {
        $c.Hint.Text = T 'win.code.incomplete'
        $first = @($c.Slots | Where-Object { -not $_.Text }) | Select-Object -First 1
        if ($first) { [void]$first.Focus() }
        return
    }
    foreach ($s in $c.Slots) { $s.IsEnabled = $false }
    if ($c.For -eq 'pair') { $c.Hint.Text = T 'ph.pairing'; Submit-HcPairCode $code; return }
    $c.Hint.Text = T 'win.code.checking'
    Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'unlock'; code = $code }; For = $c.For; Done = 'Complete-HcUnlock' }
}

function Complete-HcUnlock {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) {
        $code = if ($r) { $r.Error } else { 'unreachable' }
        $c = $w.Totp
        if ($c) {
            $c.Hint.Text = Get-HcRelayMessage $code
            $c.Hint.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'Warn')
            $c.Filling = $true
            foreach ($s in $c.Slots) { $s.Text = ''; $s.IsEnabled = $true }
            $c.Filling = $false
            [void]$c.Slots[0].Focus()
        }
        return
    }
    $script:HcToken = $r.Data.token
    $script:HcTokenExpires = [datetime]::Parse($r.Data.expires, [Globalization.CultureInfo]::InvariantCulture).ToLocalTime()
    $w.Totp = $null
    Update-HcSide
    if ($Job.For -eq 'history') {
        Start-HcHistoryLoad
    } elseif ($Job.For -eq 'ai') {
        $w.Ai.Stage = 'ask'
        Update-HcOther
    } else {
        # Who this PC belongs to, from its earlier visits: the name for the invoice.
        Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'visit_get'; token = $script:HcToken; pc = (Get-HcWindowPcId) }; Done = 'Complete-HcKnown' }
        Start-HcSettingsLoad
    }
    Update-HcVisit
}

function Get-HcWindowPcId {
    $w = $script:HcWin
    if (-not $w.PcId) { $w.PcId = Get-HcPcId }
    $w.PcId
}

function Complete-HcKnown {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) { return }
    $label = @($r.Data.visits | Where-Object { $_ -and $_.label } | Select-Object -First 1).label
    if (-not $label) { return }
    $script:HcKnownLabel = $label
    if (-not "$($w.Fin.Name)".Trim()) {
        $known = Split-HcClientName $label
        $w.Fin.Title = $known.Title
        $w.Fin.Name = $known.Name
        if ($w.Fin.Stage -eq 'form') { Update-HcVisit }
    }
}

# ------------------------------------------------------------- painting --

function Update-HcVisit {
    $w = $script:HcWin
    if ($w.Tab -ne 'visit') { return }
    if ($w.VisitView -eq 'history') { Update-HcOther; return }
    Update-HcFinishPanel
    Update-HcFinishBar
    Update-HcPreview
}

# Afronden | Eerdere bezoeken, at the top of both views.
function New-HcVisitToggle {
    $w = $script:HcWin
    $row = New-Object Windows.Controls.StackPanel
    $row.Orientation = 'Horizontal'
    $row.Margin = New-HcThickness @(0, 0, 0, 12)
    foreach ($view in @('finish', 'history')) {
        $style = if ($w.VisitView -eq $view) { 'HcPrimary' } else { 'HcButton' }
        $b = New-HcButton (T "win.visitView.$view") @{ Do = 'visitView'; View = $view } $style
        $b.Margin = New-HcThickness @(0, 0, 8, 0)
        $b.IsEnabled = -not (Test-HcBusy) -or $w.VisitView -eq $view
        [void]$row.Children.Add($b)
    }
    $row
}

function New-HcSection {
    param([string]$Title, [string]$Note)
    $head = New-Object Windows.Controls.WrapPanel
    $head.Margin = New-HcThickness @(0, 14, 0, 8)
    [void]$head.Children.Add((New-HcText $Title 17 'Text' -Bold -Margin @(0, 0, 10, 0)))
    if ($Note) {
        $n = New-HcText $Note 13 'Soft' -Margin @(0, 3, 0, 0)
        [void]$head.Children.Add($n)
    }
    $head
}

# A labelled text box that writes into $HcWin.Fin as it is typed in.
function New-HcField {
    param([string]$Label, [string]$Field, [string]$Value, [double]$Width = 0)
    $stack = New-Object Windows.Controls.StackPanel
    $stack.Margin = New-HcThickness @(0, 0, 12, 8)
    $stack.HorizontalAlignment = 'Left'
    if ($Width) { $stack.Width = $Width }
    [void]$stack.Children.Add((New-HcText $Label 13 'Soft' -Bold -Margin @(0, 0, 0, 3)))
    $box = New-HcTextBox $Value
    $box.Tag = @{ Field = $Field }
    $box.Add_TextChanged({ Invoke-HcFieldChanged $this })
    [void]$stack.Children.Add($box)
    $stack
}

function New-HcTextBox {
    param([string]$Value)
    $box = New-Object Windows.Controls.TextBox
    $box.Text = $Value
    $box.FontSize = 15
    $box.Padding = New-HcThickness @(8, 6, 8, 6)
    $box.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'Panel')
    $box.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Text')
    $box.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Line')
    $box.SetResourceReference([Windows.Controls.TextBox]::CaretBrushProperty, 'Text')
    $box
}

function New-HcChip {
    param([string]$Text, [hashtable]$Tag, [switch]$On)
    $b = New-HcButton $Text $Tag $(if ($On) { 'HcPrimary' } else { 'HcButton' })
    $b.Padding = New-HcThickness @(11, 5, 11, 5)
    $b.Margin = New-HcThickness @(0, 0, 6, 6)
    $b
}

function Update-HcFinishPanel {
    $w = $script:HcWin
    $f = $w.Fin
    $panel = $w.Window.FindName('FinishPanel')
    $panel.Children.Clear()
    $add = { param($element) [void]$panel.Children.Add($element) }
    & $add (New-HcVisitToggle)
    if ($f.Notice) { & $add (New-HcText $f.Notice 14.5 'Warn' -Bold) }

    switch ($f.Stage) {
        'code' {
            & $add (New-HcText (T 'win.visitView.finish') 22 'Text' -Bold -Margin @(0, 4, 0, 8))
            & $add (New-HcCodeBox 'finish' (T 'win.fin.codeIntro'))
            $note = New-HcButton (T 'win.fin.noteOnly') @{ Do = 'noteOnly' }
            $note.HorizontalAlignment = 'Left'
            $note.Margin = New-HcThickness @(0, 6, 0, 0)
            & $add $note
            return
        }
        'loading' {
            & $add (New-HcText (T 'win.fin.loading') 15 'Soft')
            $bar = New-Object Windows.Controls.ProgressBar
            $bar.IsIndeterminate = $true
            $bar.Height = 6
            $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
            & $add $bar
            return
        }
    }

    $done = $f.Stage -in @('working', 'done')
    $form = New-Object Windows.Controls.StackPanel
    $form.IsEnabled = -not $done
    $put = { param($element) [void]$form.Children.Add($element) }

    # What the visit was about: typed, or one of the problems opened.
    & $put (New-HcSection (T 'win.fin.asked') (T 'win.fin.askedNote'))
    if (-not "$script:HcAsked".Trim() -and $script:HcVisit.Count) { $script:HcAsked = T "problem.$($script:HcVisit[0].Code)" }
    $asked = New-HcTextBox "$script:HcAsked"
    $asked.Tag = @{ Field = 'Asked' }
    $asked.Add_TextChanged({ Invoke-HcFieldChanged $this })
    $asked.Margin = New-HcThickness @(0, 0, 0, 6)
    & $put $asked
    $chips = New-Object Windows.Controls.WrapPanel
    foreach ($v in @($script:HcVisit)) {
        [void]$chips.Children.Add((New-HcChip ($v.Code + '  ' + (T "problem.$($v.Code)")) @{ Do = 'finAsked'; Text = (T "problem.$($v.Code)") }))
    }
    & $put $chips

    # What was done: Housecall's own fixes, then Shamil's list.
    & $put (New-HcSection (T 'note.done') (T 'win.fin.doneNote'))
    foreach ($c in @($script:HcChanges)) {
        $row = New-Object Windows.Controls.DockPanel
        $tag = New-HcText 'Housecall' 11.5 'Soft' -Bold -Margin @(8, 2, 0, 0)
        [Windows.Controls.DockPanel]::SetDock($tag, 'Right')
        [void]$row.Children.Add($tag)
        [void]$row.Children.Add((New-HcLine 'ok' $c.Label))
        & $put (New-HcBox '' @($row) 'Panel')
    }
    for ($i = 0; $i -lt $script:HcWork.Count; $i++) {
        $item = $script:HcWork[$i]
        $row = New-Object Windows.Controls.DockPanel
        $buttons = New-Object Windows.Controls.StackPanel
        $buttons.Orientation = 'Horizontal'
        [Windows.Controls.DockPanel]::SetDock($buttons, 'Right')
        foreach ($state in @($true, $false)) {
            $label = if ($state) { T 'inv.win.fixed' } else { T 'inv.win.notFixed' }
            $b = New-HcChip $label @{ Do = 'workDone'; Index = $i; Done = $state } -On:($item.Done -eq $state)
            $b.Margin = New-HcThickness @(6, 0, 0, 0)
            [void]$buttons.Children.Add($b)
        }
        $x = New-HcChip ([string][char]0x00D7) @{ Do = 'workRemove'; Index = $i }
        $x.Margin = New-HcThickness @(6, 0, 0, 0)
        $x.ToolTip = T 'win.fin.remove'
        [void]$buttons.Children.Add($x)
        [void]$row.Children.Add($buttons)
        [void]$row.Children.Add((New-HcLine $(if ($item.Done) { 'ok' } else { 'problem' }) $item.Text))
        $box = New-HcBox '' @($row) 'Panel'
        $box.Padding = New-HcThickness @(10, 6, 6, 4)
        $box.Margin = New-HcThickness @(0, 0, 0, 6)
        & $put $box
    }
    $addRow = New-Object Windows.Controls.DockPanel
    $addRow.Margin = New-HcThickness @(0, 4, 0, 6)
    $addButton = New-HcButton (T 'win.fin.add') @{ Do = 'workAdd' }
    $addButton.Margin = New-HcThickness @(8, 0, 0, 0)
    [Windows.Controls.DockPanel]::SetDock($addButton, 'Right')
    [void]$addRow.Children.Add($addButton)
    $w.WorkBox = New-HcTextBox ''
    $w.WorkBox.Tag = @{ Do = 'workAdd' }
    $w.WorkBox.Add_KeyDown({ if ($_.Key -eq 'Return') { Invoke-HcClick $this } })
    [void]$addRow.Children.Add($w.WorkBox)
    & $put $addRow
    # The most used first; the rest behind "more", so the form stays short.
    $presets = New-Object Windows.Controls.WrapPanel
    $left = @(Get-HcWorkPresets | Where-Object { $p = $_; -not @($script:HcWork | Where-Object { $_.Text -eq $p }).Count })
    $shown = if ($f.AllPresets) { $left } else { @($left | Select-Object -First 8) }
    foreach ($p in $shown) { [void]$presets.Children.Add((New-HcChip ('+ ' + $p) @{ Do = 'workPreset'; Text = $p })) }
    if ($left.Count -gt $shown.Count) { [void]$presets.Children.Add((New-HcChip (T 'win.fin.more' ($left.Count - $shown.Count)) @{ Do = 'morePresets' })) }
    & $put $presets

    # The client.
    & $put (New-HcSection (T 'win.fin.client') $(if ($f.Mode -eq 'note') { T 'win.fin.clientNote' } else { '' }))
    # The salutation, picked with one click: it goes before the name.
    [void]$form.Children.Add((New-HcText (T 'win.fin.title') 13 'Soft' -Bold -Margin @(0, 0, 0, 3)))
    $titles = New-Object Windows.Controls.WrapPanel
    foreach ($t in @(Get-HcTitleChoices)) {
        [void]$titles.Children.Add((New-HcChip (T "win.title.$t") @{ Do = 'clientTitle'; Title = $t } -On:($f.Title -eq $t -or ($t -eq 'mrs' -and $f.Title -eq 'ms' -and $script:Lang -eq 'nl'))))
    }
    & $put $titles
    & $put (New-HcText (T 'win.fin.titleNote') 13 'Soft' -Margin @(0, 0, 0, 8))
    $grid = New-Object Windows.Controls.WrapPanel
    [void]$grid.Children.Add((New-HcField (T 'win.fin.fullName') 'Name' $f.Name 250))
    [void]$grid.Children.Add((New-HcField (T 'win.fin.email') 'Email' $f.Email 250))
    [void]$grid.Children.Add((New-HcField (T 'inv.address') 'Address' $f.Address 250))
    [void]$grid.Children.Add((New-HcField (T 'inv.postcode') 'Postcode' $f.Postcode 250))
    & $put $grid

    if ($f.Mode -in @('invoice', 'receipt') -and $f.Settings) {
        # Time and costs.
        & $put (New-HcSection (T 'win.fin.time'))
        $clock = Get-HcClockLine
        & $put (New-HcText $clock.Text 15 $(if ($clock.Over) { 'Warn' } else { 'Text' }) -Bold)
        $minutes = New-HcField (T 'inv.win.minutes') 'Minutes' ([string]$f.Minutes) 140
        & $put $minutes
        & $put (New-HcText (Get-HcRateText $f.Settings) 13.5 'Soft')
        $fee = [decimal]$(if ($f.Settings.callout_fee) { $f.Settings.callout_fee } else { 0 })
        if ($fee -gt 0) {
            $check = New-Object Windows.Controls.CheckBox
            $check.Content = T 'inv.win.callout' (Format-HcMoney $fee)
            $check.IsChecked = [bool]$f.Callout
            $check.Tag = @{ Field = 'Callout' }
            $check.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Text')
            $check.Margin = New-HcThickness @(0, 4, 0, 8)
            $check.Add_Click({ Invoke-HcFieldChanged $this })
            & $put $check
        }
        # Parts, each with its price.
        foreach ($e in @($f.Extras)) {
            $i = $f.Extras.IndexOf($e)
            $row = New-Object Windows.Controls.DockPanel
            $x = New-HcChip ([string][char]0x00D7) @{ Do = 'extraRemove'; Index = $i }
            [Windows.Controls.DockPanel]::SetDock($x, 'Right')
            [void]$row.Children.Add($x)
            [void]$row.Children.Add((New-HcText ($e.Description + '   ' + (Format-HcMoney $e.Amount)) 15 'Text' -Margin @(0, 4, 0, 0)))
            $box = New-HcBox '' @($row) 'Panel'
            $box.Padding = New-HcThickness @(12, 6, 6, 0)
            $box.Margin = New-HcThickness @(0, 0, 0, 6)
            & $put $box
        }
        $extra = New-Object Windows.Controls.WrapPanel
        $w.ExtraText = New-HcField (T 'win.fin.part') 'ExtraText' '' 250
        $w.ExtraPrice = New-HcField (T 'win.fin.price') 'ExtraPrice' '' 110
        [void]$extra.Children.Add($w.ExtraText)
        [void]$extra.Children.Add($w.ExtraPrice)
        $addPart = New-HcButton (T 'win.fin.add') @{ Do = 'extraAdd' }
        $addPart.VerticalAlignment = 'Bottom'
        [void]$extra.Children.Add($addPart)
        & $put $extra
        $f.CalcBlock = New-HcText '' 14 'Soft' -Margin @(0, 4, 0, 0)
        & $put $f.CalcBlock
        Update-HcCalc

        # How it is paid.
        & $put (New-HcSection (T 'inv.win.payment'))
        $pay = New-Object Windows.Controls.WrapPanel
        foreach ($m in @(Get-HcPayMethods $f.Settings -Receipt:($f.Mode -eq 'receipt'))) {
            $label = T ('inv.pay.' + $m)
            $label = $label.Substring(0, 1).ToUpperInvariant() + $label.Substring(1)
            if ($m -eq 'transfer') { $label += ' (' + (T 'win.fin.days' $(if ($f.Settings.payment_days) { $f.Settings.payment_days } else { 14 })) + ')' }
            [void]$pay.Children.Add((New-HcChip $label @{ Do = 'pay'; Method = $m } -On:($f.Payment -eq $m)))
        }
        & $put $pay
    }
    & $add $form
}

# "Arbeid 50 min: starttarief ... EUR 15,00 . + 2 x 15 min ... EUR 10,00 . Totaal EUR 25,00"
function Update-HcCalc {
    $f = $script:HcWin.Fin
    if (-not $f.CalcBlock -or -not $f.Settings) { return }
    $lines = @(Get-HcDraftLines $f $f.Settings)
    $total = [decimal]0
    foreach ($l in $lines) { $total += [decimal]$l.Amount }
    $dot = '  ' + [char]0x00B7 + '  '
    # A non-breaking space after the euro sign, so an amount never splits.
    $money = { param($a) (Format-HcMoney $a) -replace ([string][char]0x20AC + ' '), ([string][char]0x20AC + [char]0x00A0) }
    $parts = @($lines | ForEach-Object { $_.Description + ': ' + (& $money $_.Amount) })
    $f.CalcBlock.Text = (@($parts) + @((T 'doc.totalWord') + ' ' + (& $money $total))) -join $dot
}

function Update-HcFinishBar {
    $w = $script:HcWin
    $f = $w.Fin
    $bar = $w.Window.FindName('FinishBar')
    $bar.Children.Clear()
    $row = New-Object Windows.Controls.WrapPanel
    $add = { param($element) $element.Margin = New-HcThickness @(0, 0, 8, 6); [void]$row.Children.Add($element) }
    $hint = $null
    if ($w.CloseAsk) { [void]$bar.Children.Add((New-HcText (T 'win.fin.closeFirst') 14.5 'Warn' -Bold)) }
    if ($f.MailAsk) { [void]$bar.Children.Add((New-HcQuestion (T "win.mail.ask.$(Get-HcDocKind)" $f.MailAsk) 'mailYes' 'mailNo')) }
    if ($f.MailBusy) { [void]$bar.Children.Add((New-HcText (T 'win.mail.busy') 14.5 'Soft' -Bold)) }
    elseif ($f.MailResult) { [void]$bar.Children.Add((New-HcText $f.MailResult.Text 14.5 $(if ($f.MailResult.Ok) { 'Ok' } else { 'Warn' }) -Bold)) }
    $mail = { if (-not $f.Offline) { & $add (New-HcButton (T 'win.fin.mail') @{ Do = 'finMail' }) } }
    switch ($f.Stage) {
        'working' { $hint = T 'win.fin.working' }
        'done' {
            if ($f.Invoice) {
                [void]$bar.Children.Add((New-HcText ([string][char]0x2713 + ' ' + (T 'win.fin.made' $f.Invoice.number) + $(if ($f.Saved) { ' ' + (T 'win.fin.savedToo') } else { '' })) 15 'Ok' -Bold))
            }
            & $add (New-HcButton (T 'note.print') @{ Do = 'finPrint' } 'HcPrimary')
            & $add (New-HcButton (T 'win.fin.pdf') @{ Do = 'finPdf' })
            & $mail
            & $add (New-HcButton (T 'win.fin.close') @{ Do = 'finDone' })
        }
        'form' {
            if ($f.Mode -eq 'invoice' -and $f.Settings) {
                & $add (New-HcButton (T 'win.fin.make') @{ Do = 'finMake' } 'HcPrimary')
                $hint = T 'win.fin.makeHint'
            } elseif ($f.Mode -eq 'receipt' -and $f.Settings) {
                & $add (New-HcButton (T 'win.fin.receiptPrint') @{ Do = 'finPrint' } 'HcPrimary')
                & $add (New-HcButton (T 'win.fin.pdf') @{ Do = 'finPdf' })
                & $mail
                & $add (New-HcButton (T 'win.fin.close') @{ Do = 'finDone' })
                $hint = T 'win.fin.receiptHint'
            } else {
                & $add (New-HcButton (T 'win.fin.notePrint') @{ Do = 'finPrint' } 'HcPrimary')
                & $add (New-HcButton (T 'win.fin.pdf') @{ Do = 'finPdf' })
                & $mail
                & $add (New-HcButton (T 'win.fin.close') @{ Do = 'finDone' })
                $hint = if ($f.Offline) { T 'win.fin.noteOffline' } elseif (Test-HcUnlocked) { T 'win.fin.noteSaves' } else { T 'win.fin.noteNoCode' }
            }
        }
    }
    # Last, as the least wanted way out.
    if ($w.CloseAsk -and $f.Stage -ne 'done') { & $add (New-HcButton (T 'win.fin.closeAnyway') @{ Do = 'closeAnyway' }) }
    if ($row.Children.Count) { [void]$bar.Children.Add($row) }
    if ($hint) { [void]$bar.Children.Add((New-HcText $hint 13 'Soft' -Margin @(0, 0, 0, 0))) }
    $w.Window.FindName('FinishBarBorder').Visibility = if ($bar.Children.Count) { 'Visible' } else { 'Collapsed' }
}

# The A4 page on the right: the invoice being filled in, the finished one,
# or the note. Drawn by the same code as the printout.
function Update-HcPreview {
    $w = $script:HcWin
    $f = $w.Fin
    if ($w.Tab -ne 'visit' -or $w.VisitView -ne 'finish') { return }
    $top = $w.Window.FindName('PreviewTop')
    $top.Children.Clear()
    $panel = $w.Window.FindName('PreviewPanel')
    $panel.Children.Clear()

    $state = if ($f.Stage -eq 'done' -and $f.Invoice) { T 'win.fin.stateMade' $f.Invoice.number }
             elseif ($f.Mode -eq 'note') { T 'win.fin.stateNote' }
             elseif ($f.Mode -eq 'receipt') { T 'win.fin.stateReceipt' }
             else { T 'win.fin.stateDraft' }
    $label = New-HcText $state.ToUpperInvariant() 12 $(if ($f.Invoice) { 'Ok' } else { 'Soft' }) -Bold -Margin @(0, 8, 0, 0)
    [Windows.Controls.DockPanel]::SetDock($label, 'Left')
    [void]$top.Children.Add($label)
    if ($f.Stage -ne 'done') {
        $modes = New-Object Windows.Controls.StackPanel
        $modes.Orientation = 'Horizontal'
        [Windows.Controls.DockPanel]::SetDock($modes, 'Right')
        foreach ($m in @('invoice', 'receipt', 'note')) {
            $b = New-HcChip (T "win.fin.mode.$m") @{ Do = 'finMode'; Mode = $m } -On:($f.Mode -eq $m)
            $b.IsEnabled = -not ($m -ne 'note' -and $f.Offline) -and $f.Stage -ne 'working'
            [void]$modes.Children.Add($b)
        }
        [void]$top.Children.Add($modes)
    }

    if ($f.Mode -in @('invoice', 'receipt') -and -not $f.Settings -and -not $f.Invoice) {
        [void]$panel.Children.Add((New-HcText (T 'win.fin.previewAfterCode') 14.5 'Soft' -Margin @(0, 12, 0, 0)))
        $f.Pages = $null
        return
    }
    try {
        # One @() around the whole choice: each page is an array of steps,
        # and an if-statement would unroll the list of pages into its steps.
        $pages = @(if ($f.Invoice) { Get-HcInvoiceLayout $f.Invoice }
                   elseif ($f.Mode -eq 'note') { Get-HcInvoiceLayout (New-HcDraftInvoice $f $f.Settings) -Note }
                   elseif ($f.Mode -eq 'receipt') { Get-HcInvoiceLayout (New-HcDraftInvoice $f $f.Settings) -Receipt }
                   else { Get-HcInvoiceLayout (New-HcDraftInvoice $f $f.Settings) })
    } catch {
        [void]$panel.Children.Add((New-HcText (T 'win.error' $_.Exception.Message) 14 'Warn'))
        return
    }
    $f.Pages = $pages
    foreach ($steps in $pages) {
        $bmp = New-HcInvoiceBitmap $steps
        $stream = New-Object IO.MemoryStream
        try {
            $bmp.Save($stream, [Drawing.Imaging.ImageFormat]::Png)
            $stream.Position = 0
            $source = New-Object Windows.Media.Imaging.BitmapImage
            $source.BeginInit()
            $source.CacheOption = 'OnLoad'
            $source.StreamSource = $stream
            $source.EndInit()
            $source.Freeze()
        } finally {
            $stream.Dispose()
            $bmp.Dispose()
        }
        $image = New-Object Windows.Controls.Image
        $image.Source = $source
        $image.Stretch = 'Uniform'
        [Windows.Media.RenderOptions]::SetBitmapScalingMode($image, 'HighQuality')
        $paper = New-Object Windows.Controls.Border
        $paper.Background = [Windows.Media.Brushes]::White
        $paper.Margin = New-HcThickness @(0, 0, 0, 14)
        $paper.Effect = New-Object Windows.Media.Effects.DropShadowEffect -Property @{ BlurRadius = 14; ShadowDepth = 2; Opacity = 0.25 }
        $paper.Child = $image
        [void]$panel.Children.Add($paper)
    }
}

# A redraw a moment after the last keystroke, not on every one.
function Request-HcPreview {
    $script:HcWin.PreviewDue = (Get-Date).AddMilliseconds(300)
}

# ---------------------------------------------------------------- doing --

function Invoke-HcFieldChanged {
    param($Sender)
    $w = $script:HcWin
    $f = $w.Fin
    $field = $Sender.Tag.Field
    switch ($field) {
        'Asked'    { $script:HcAsked = "$($Sender.Text)".Trim() }
        'Minutes'  {
            $n = 0
            if ([int]::TryParse("$($Sender.Text)".Trim(), [ref]$n) -and $n -ge 0 -and $n -le 1440) { $f.Minutes = $n }
            Update-HcCalc
        }
        'Callout'  { $f.Callout = [bool]$Sender.IsChecked; Update-HcCalc }
        'ExtraText' { return }
        'ExtraPrice' { return }
        default    { $f[$field] = "$($Sender.Text)" }
    }
    $f.Notice = $null
    Request-HcPreview
}

function Invoke-HcVisitClick {
    param([hashtable]$Tag)
    $w = $script:HcWin
    $f = $w.Fin
    switch ($Tag.Do) {
        'visitView'  { Open-HcVisitTab $Tag.View }
        'finAsked'   { $script:HcAsked = $Tag.Text; Update-HcVisit }
        'workPreset' { [void](Add-HcWorkItem $Tag.Text $true); Update-HcVisit }
        'morePresets' { $f.AllPresets = $true; Update-HcFinishPanel }
        'workAdd'    { if (Add-HcWorkItem $w.WorkBox.Text $true) { Update-HcVisit; [void]$w.WorkBox.Focus() } }
        'workDone'   { $script:HcWork[$Tag.Index].Done = $Tag.Done; Update-HcVisit }
        'workRemove' { $script:HcWork.RemoveAt($Tag.Index); Update-HcVisit }
        'extraAdd'   {
            $text = "$($w.ExtraText.Children[1].Text)".Trim()
            $amount = ConvertTo-HcAmount $w.ExtraPrice.Children[1].Text
            if (-not $text -or $null -eq $amount) { $f.Notice = T 'win.fin.badPart'; Update-HcFinishPanel; return }
            [void]$f.Extras.Add([pscustomobject]@{ Description = $text; Amount = $amount })
            $f.Notice = $null
            Update-HcVisit
        }
        'extraRemove' { $f.Extras.RemoveAt($Tag.Index); Update-HcVisit }
        'pay'        { $f.Payment = $Tag.Method; Update-HcVisit }
        'clientTitle' { $f.Title = $Tag.Title; Update-HcVisit }
        'finMode'    {
            # A receipt has no paying later.
            if ($Tag.Mode -eq 'receipt' -and $f.Payment -eq 'transfer') { $f.Payment = 'pin' }
            if ($Tag.Mode -in @('invoice', 'receipt') -and -not $f.Settings) {
                $f.Mode = $Tag.Mode
                if (Test-HcUnlocked) { Start-HcSettingsLoad } else { $f.Stage = 'code' }
            } else {
                $f.Mode = $Tag.Mode
                # The note needs no code: leave the code slots for the note's form.
                if ($f.Mode -eq 'note' -and $f.Stage -in @('code', 'new')) { $f.Stage = 'form'; $w.Totp = $null }
            }
            $f.Notice = $null
            Update-HcVisit
        }
        'noteOnly'   { $f.Mode = 'note'; $f.Stage = 'form'; $w.Totp = $null; Update-HcVisit }
        'codeSubmit' { Submit-HcCode }
        'finMake'    { Start-HcMakeInvoice }
        'finPrint'   {
            if (-not $f.Pages) { Update-HcPreview }
            $script:HcInvoicePages = $f.Pages
            Invoke-HcInvoicePrint
        }
        'finPdf'     { Save-HcWindowPdf }
        'finMail'    { Request-HcMail }
        'mailYes'    { Send-HcMail }
        'mailNo'     { $f.MailAsk = $null; Update-HcFinishBar }
        'finDone'    { Complete-HcVisitWindow }
        'closeAnyway' { $w.CloseAnyway = $true; $w.Outcome = 'done'; $w.Window.Close() }
        'histDelete' { $w.Hist.Confirm = $Tag.Id; $w.Hist.Notice = $null; Update-HcOther }
        'histNo'     { $w.Hist.Confirm = $null; Update-HcOther }
        'histDoc'    { Open-HcKeptDoc $Tag.Id }
        'histYes'    {
            $visit = @($w.Hist.Visits | Where-Object { [long]$_.id -eq [long]$w.Hist.Confirm }) | Select-Object -First 1
            $w.Hist.Confirm = $null
            $w.Hist.Stage = 'loading'
            Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'visit_delete'; token = $script:HcToken; pc = (Get-HcWindowPcId); id = [long]$visit.id }
                         Visit = $visit; Done = 'Complete-HcHistoryDelete' }
            Update-HcOther
        }
    }
}

# Checks the form the way the text menu's window did, then lets the relay
# number and keep it, and saves the visit with it.
function Start-HcMakeInvoice {
    $w = $script:HcWin
    $f = $w.Fin
    $check = ConvertTo-HcInvoiceForm @{
        Name = (Format-HcClientName $f.Title $f.Name); Address = $f.Address; Postcode = $f.Postcode; Email = $f.Email
        Minutes = $f.Minutes; Callout = $f.Callout; Payment = $f.Payment
        Extras = @($f.Extras | ForEach-Object { [pscustomobject]@{ Description = $_.Description; Amount = ([decimal]$_.Amount).ToString([Globalization.CultureInfo]::InvariantCulture) } })
    } $f.Settings
    if ($check.Error) { $f.Notice = $check.Error; Update-HcFinishPanel; return }
    $f.Notice = $null
    $f.Stage = 'working'
    Add-HcJob @{ Kind = 'relay'; Body = (New-HcInvoiceBody $check.Form (Get-HcWindowPcId)); Done = 'Complete-HcInvoiceMade' }
    Update-HcVisit
}

function Complete-HcInvoiceMade {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $f = $w.Fin
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) {
        $code = if ($r) { $r.Error } else { 'unreachable' }
        if ($code -eq 'locked_out') { $script:HcToken = $null; $f.Stage = 'code'; $f.Notice = T 'relay.expired' }
        else { $f.Stage = 'form'; $f.Notice = T 'inv.failed' (Get-HcRelayMessage $code) }
        Update-HcVisit
        return
    }
    $f.Invoice = $r.Data.invoice
    $f.Stage = 'done'
    $w.CloseAsk = $false
    Add-HcJob @{ Kind = 'relay'; Body = (New-HcVisitBody $w.Environment ([string]$f.Invoice.client_name) ([string]$f.Invoice.number) (Get-HcWindowPcId)); Done = 'Complete-HcVisitSaved' }
    Update-HcVisit
}

function Complete-HcVisitSaved {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $f = $w.Fin
    $r = Get-HcRelayResult $Output
    if (-not $ErrorText -and $r -and $r.Ok) {
        $f.Saved = $true
        if ($r.Data.id) { $f.VisitId = [long]$r.Data.id }
        # A list read before this save lacks it: read it again when shown.
        if ($w.Hist.Stage -eq 'list') { $w.Hist.Stage = 'new' }
    }
    else { $f.Notice = T 'mem.notSaved' (Get-HcRelayMessage $(if ($r) { $r.Error } else { 'unreachable' })) }
    if ($Job.ThenClose) {
        if (Test-HcDocWanted) { Start-HcDocSave; return }
        $w.Outcome = 'done'; $w.Finished = $true; $w.Window.Close(); return
    }
    Update-HcFinishBar
    Update-HcFinishPanel
}

# Klaar: with a note, the visit is still saved when the code was given.
function Complete-HcVisitWindow {
    $w = $script:HcWin
    $f = $w.Fin
    $worth = $script:HcVisit.Count -gt 0 -or $script:HcWork.Count -gt 0
    if (-not $f.Invoice -and -not $f.Saved -and $worth -and -not $script:DryRun -and $w.Environment.Online -and (Test-HcUnlocked)) {
        $f.Stage = 'working'
        $label = if ("$($f.Name)".Trim()) { Format-HcClientName $f.Title $f.Name } else { $script:HcKnownLabel }
        Add-HcJob @{ Kind = 'relay'; Body = (New-HcVisitBody $w.Environment $label $null (Get-HcWindowPcId)); ThenClose = $true; Done = 'Complete-HcVisitSaved' }
        Update-HcVisit
        return
    }
    if (Test-HcDocWanted) { Start-HcDocSave; return }
    $w.Outcome = 'done'
    $w.Finished = $true
    $w.Window.Close()
}

# "Factuur 2026-0005.pdf", "Betaalbewijs 2026-09-28.pdf" or "Briefje 2026-09-28.pdf".
function Get-HcPdfName {
    $f = $script:HcWin.Fin
    $today = Get-Date -Format 'yyyy-MM-dd'
    if ($f.Invoice) { return (T 'win.fin.pdfInvoice' $f.Invoice.number) }
    if ($f.Mode -eq 'receipt') { return (T 'win.fin.pdfReceipt' $today) }
    T 'win.fin.pdfNote' $today
}

# invoice, receipt or note: which document the visit ends with.
function Get-HcDocKind {
    $f = $script:HcWin.Fin
    if ($f.Invoice) { 'invoice' } elseif ($f.Mode -eq 'receipt') { 'receipt' } else { 'note' }
}

# The client's address for the mail: the one on the invoice, else the form's.
function Get-HcMailTo {
    $f = $script:HcWin.Fin
    $to = if ($f.Invoice -and $f.Invoice.client_email) { [string]$f.Invoice.client_email } else { "$($f.Email)".Trim() }
    if ($to -match '^[^\s@<>(),;:"\\]+@[^\s@<>(),;:"\\]+\.[a-zA-Z]{2,}$') { $to } else { $null }
}

# Mail naar klant: an address, the code (the relay sends it), then a Ja/Nee.
function Request-HcMail {
    $w = $script:HcWin
    $f = $w.Fin
    $f.MailResult = $null
    $to = Get-HcMailTo
    if (-not $to) { $f.MailResult = @{ Ok = $false; Text = (T 'win.mail.needAddress') }; Update-HcFinishBar; return }
    if (-not (Test-HcUnlocked)) {
        if ($f.Stage -eq 'form') { $f.Stage = 'code'; $f.Notice = T 'win.mail.needCode'; Update-HcVisit }
        else { $f.MailResult = @{ Ok = $false; Text = (T 'relay.expired') }; Update-HcFinishBar }
        return
    }
    $f.MailAsk = $to
    Update-HcFinishBar
}

# The page as a PDF (Windows' own PDF printer, into a temporary file that is
# gone straight after), then through the relay from Shamil's Outlook.
function Send-HcMail {
    $w = $script:HcWin
    $f = $w.Fin
    $to = $f.MailAsk
    $f.MailAsk = $null
    if (-not $f.Pages) { Update-HcPreview }
    # Printed by the worker, like the document at the end: the window stays
    # responsive while Windows' PDF printer works.
    Add-HcJob @{ Kind = 'pdf'; Body = @{ Pages = @($f.Pages) }; To = $to; Done = 'Complete-HcMailPdf' }
    $f.MailBusy = $true
    Update-HcFinishBar
}

function Complete-HcMailPdf {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $f = $script:HcWin.Fin
    $r = Get-HcPdfResult $Output
    if ($ErrorText -or -not $r -or -not $r.PdfBytes) {
        $why = if ($ErrorText) { $ErrorText } elseif ($r) { $r.PdfProblem } else { '' }
        $f.MailBusy = $false
        $f.MailResult = @{ Ok = $false; Text = (T 'win.fin.pdfFailed' "$why") }
        Update-HcFinishBar
        return
    }
    $to = $Job.To
    $kind = Get-HcDocKind
    $mail = New-HcMailText $kind $f.Title $f.Name (Get-Date) $(if ($f.Invoice) { [string]$f.Invoice.number } else { '' }) $f.Settings
    Add-HcJob @{ Kind = 'relay'; To = $to; Done = 'Complete-HcMailSent'; Body = @{
        action = 'mail_send'; token = $script:HcToken; to = $to; subject = $mail.Subject; text = $mail.Text
        pdf_base64 = [Convert]::ToBase64String($r.PdfBytes); filename = (Get-HcPdfName) } }
}

function Complete-HcMailSent {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $f = $script:HcWin.Fin
    $f.MailBusy = $false
    $r = Get-HcRelayResult $Output
    if (-not $ErrorText -and $r -and $r.Ok) { $f.MailResult = @{ Ok = $true; Text = (T 'win.mail.sent' $Job.To) } }
    else { $f.MailResult = @{ Ok = $false; Text = (Get-HcRelayMessage $(if ($r) { $r.Error } else { 'unreachable' })) } }
    Update-HcFinishBar
}

# Opslaan als PDF: Windows' own PDF printer, to a file the client can get
# by email. Documents by default; the name says what it is.
function Save-HcWindowPdf {
    $w = $script:HcWin
    $f = $w.Fin
    if (-not $f.Pages) { Update-HcPreview }
    if (-not $f.Pages) { return }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Filter = 'PDF (*.pdf)|*.pdf'
    $dialog.InitialDirectory = [Environment]::GetFolderPath('MyDocuments')
    $dialog.FileName = Get-HcPdfName
    if (-not $dialog.ShowDialog($w.Window)) { return }
    $script:HcInvoicePages = $f.Pages
    $problem = Save-HcPagesPdf $dialog.FileName
    $f.Notice = if ($problem) { T 'win.fin.pdfFailed' $problem } else { T 'win.fin.pdfSaved' $dialog.FileName }
    Update-HcFinishPanel
}

# --------------------------------------------------- the kept document --

# Klaar keeps the PDF the visit ended with in Shamil's own storage behind
# the relay (7 Oct): the invoice once it is made, else the receipt, else the
# note. It needs the code; a note without the code is not kept.
function Test-HcDocWanted {
    $w = $script:HcWin
    $f = $w.Fin
    if ($script:DryRun -or -not $w.Environment.Online -or -not (Test-HcUnlocked) -or $f.DocSaved -or $f.DocFailed) { return $false }
    switch (Get-HcDocKind) {
        'invoice' { return $true }
        'receipt' { return ([bool]$f.Settings -and (New-HcDraftInvoice $f $f.Settings).total -gt 0) }
        default   { return ($script:HcVisit.Count -gt 0 -or $script:HcWork.Count -gt 0) }
    }
}

# The pages of that document. An invoice that was never made is no
# document, so the visit then ends with the note.
function Get-HcDocPages {
    param([hashtable]$Fin, [string]$Kind)
    switch ($Kind) {
        'invoice' { @(Get-HcInvoiceLayout $Fin.Invoice) }
        'receipt' { @(Get-HcInvoiceLayout (New-HcDraftInvoice $Fin $Fin.Settings) -Receipt) }
        default   { @(Get-HcInvoiceLayout (New-HcDraftInvoice $Fin $Fin.Settings) -Note) }
    }
}

# What doc_save gets: the PDF and what it is about, for the overview.
function New-HcDocBody {
    param([hashtable]$Fin, [string]$Kind, [byte[]]$Pdf, [string]$PcId, [string]$Label)
    $total = $null; $payment = $null; $number = $null; $client = $Label
    if ($Kind -eq 'invoice') {
        $total = [double]$Fin.Invoice.total; $payment = [string]$Fin.Invoice.payment
        $number = [string]$Fin.Invoice.number; $client = [string]$Fin.Invoice.client_name
    } elseif ($Kind -eq 'receipt') {
        $total = [double](New-HcDraftInvoice $Fin $Fin.Settings).total; $payment = [string]$Fin.Payment
    }
    if ($client -and $client.Length -gt 100) { $client = $client.Substring(0, 100) }
    @{
        action = 'doc_save'; token = $script:HcToken; id = $Fin.DocId; pc = $PcId
        visit_id = $(if ($Fin.VisitId) { [long]$Fin.VisitId } else { $null })
        kind = $Kind; client_name = $(if ($client) { $client } else { $null }); invoice_number = $number
        total = $total; payment = $(if ($payment) { $payment } else { $null }); lang = $script:Lang
        pdf_base64 = [Convert]::ToBase64String($Pdf)
    }
}

function Start-HcDocSave {
    $w = $script:HcWin
    $f = $w.Fin
    $kind = Get-HcDocKind
    $f.StageBefore = $f.Stage
    try {
        $pages = @(Get-HcDocPages $f $kind)
    } catch {
        Complete-HcDocSaved @{} @() (T 'win.fin.pdfFailed' $_.Exception.Message) @()
        return
    }
    # The PDF is printed by the worker, so the window says it is busy rather
    # than freezing; Complete-HcDocPdf then sends it to the relay.
    $f.Stage = 'working'
    Add-HcJob @{ Kind = 'pdf'; Body = @{ Pages = $pages }; DocKind = $kind; Done = 'Complete-HcDocPdf' }
    Update-HcVisit
}

# The PDF a worker job printed, or why it could not.
function Get-HcPdfResult {
    param([object[]]$Output)
    @($Output | Where-Object { $_ -is [hashtable] -and ($_.ContainsKey('PdfBytes') -or $_.ContainsKey('PdfProblem')) }) | Select-Object -Last 1
}

function Complete-HcDocPdf {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $f = $script:HcWin.Fin
    $r = Get-HcPdfResult $Output
    if ($ErrorText -or -not $r -or -not $r.PdfBytes) {
        $why = if ($ErrorText) { $ErrorText } elseif ($r) { $r.PdfProblem } else { '' }
        Complete-HcDocSaved @{} @() (T 'win.fin.pdfFailed' "$why") @()
        return
    }
    $label = if ("$($f.Name)".Trim()) { Format-HcClientName $f.Title $f.Name } else { $script:HcKnownLabel }
    Add-HcJob @{ Kind = 'relay'; Body = (New-HcDocBody $f $Job.DocKind $r.PdfBytes (Get-HcWindowPcId) $label); Done = 'Complete-HcDocSaved' }
}

# Kept: the window closes. Not kept: it says so and stays open; Klaar again
# closes without trying again.
function Complete-HcDocSaved {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $f = $w.Fin
    $r = Get-HcRelayResult $Output
    if (-not $ErrorText -and $r -and $r.Ok) {
        $f.DocSaved = $true
        $w.Outcome = 'done'; $w.Finished = $true; $w.Window.Close()
        return
    }
    $f.DocFailed = $true
    $why = if ($ErrorText) { $ErrorText } else { Get-HcRelayMessage $(if ($r) { $r.Error } else { 'unreachable' }) }
    $f.Notice = T 'doc.notKept' $why
    if ($f.StageBefore) { $f.Stage = $f.StageBefore }
    Update-HcVisit
}

# A kept PDF opened from the history: into the temporary folder, opened
# with the PDF viewer, and removed when Housecall closes (Remove-HcOpenedDocs).
function Open-HcKeptDoc {
    param([string]$Id)
    $h = $script:HcWin.Hist
    $h.Notice = T 'doc.opening'
    Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'doc_get'; token = $script:HcToken; id = $Id }; Done = 'Complete-HcKeptDoc' }
    Update-HcOther
}

function Complete-HcKeptDoc {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $h = $script:HcWin.Hist
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok -or -not $r.Data.pdf_base64) {
        $h.Notice = Get-HcRelayMessage $(if ($r -and $r.Error) { $r.Error } else { 'unreachable' })
        Update-HcOther
        return
    }
    $path = Join-Path $env:TEMP ('housecall-doc-' + [guid]::NewGuid().ToString('N') + '.pdf')
    try {
        [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String([string]$r.Data.pdf_base64))
        Start-Process -FilePath $path -ErrorAction Stop
        $h.Notice = $null
    } catch {
        $h.Notice = T 'doc.openFailed' $_.Exception.Message
    }
    Update-HcOther
}

function Remove-HcOpenedDocs {
    Get-ChildItem -Path $env:TEMP -Filter 'housecall-doc-*.pdf' -ErrorAction SilentlyContinue |
        Remove-Item -Force -ErrorAction SilentlyContinue
}

# "Betaalbewijs  EUR 32,50  pin": a kept document in one line.
function Format-HcDocLine {
    param($Doc)
    $parts = @(if ($Doc.kind -eq 'invoice' -and $Doc.invoice_number) { T 'mem.invoice' $Doc.invoice_number } else { T "doc.kind.$($Doc.kind)" })
    if ($null -ne $Doc.total -and "$($Doc.total)" -ne '') { $parts += Format-HcMoney ([decimal]$Doc.total) }
    if ($Doc.payment) { $parts += T "inv.pay.$($Doc.payment)" }
    $parts -join ('  ' + [char]0x00B7 + '  ')
}

# -------------------------------------------------------------- history --

function Start-HcHistory {
    $w = $script:HcWin
    $h = $w.Hist
    if (-not $w.Environment.Online) { $h.Stage = 'offline'; return }
    if ($h.Stage -in @('loading', 'list')) { return }
    if (Test-HcUnlocked) { Start-HcHistoryLoad } else { $h.Stage = 'code' }
}

function Start-HcHistoryLoad {
    $h = $script:HcWin.Hist
    $h.Stage = 'loading'
    Add-HcJob @{ Kind = 'relay'; Body = @{ action = 'visit_get'; token = $script:HcToken; pc = (Get-HcWindowPcId) }; Done = 'Complete-HcHistory' }
}

function Complete-HcHistory {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $h = $w.Hist
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) {
        $code = if ($r) { $r.Error } else { 'unreachable' }
        if ($code -eq 'locked_out') { $script:HcToken = $null; $h.Stage = 'code'; $h.Notice = T 'relay.expired' }
        else { $h.Stage = 'list'; $h.Visits = @(); $h.Notice = Get-HcRelayMessage $code }
    } else {
        $h.Visits = @($r.Data.visits | Where-Object { $_ })
        $h.Docs = @($r.Data.documents | Where-Object { $_ })
        $h.Stage = 'list'
        $label = @($h.Visits | Where-Object { $_.label } | Select-Object -First 1).label
        if ($label) {
            $script:HcKnownLabel = $label
            if (-not "$($w.Fin.Name)".Trim()) { $known = Split-HcClientName $label; $w.Fin.Title = $known.Title; $w.Fin.Name = $known.Name }
        }
    }
    Update-HcOther
}

function Complete-HcHistoryDelete {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $h = $script:HcWin.Hist
    $r = Get-HcRelayResult $Output
    if ($ErrorText -or -not $r -or -not $r.Ok) {
        $h.Notice = Get-HcRelayMessage $(if ($r) { $r.Error } else { 'unreachable' })
    } else {
        $h.Notice = T 'mem.deleted'
        if ($Job.Visit.invoice_number) { $h.Notice += ' ' + (T 'mem.invoiceKept' $Job.Visit.invoice_number) }
    }
    Start-HcHistoryLoad
    Update-HcOther
}

function Update-HcHistoryPanel {
    param($Panel)
    $w = $script:HcWin
    $h = $w.Hist
    $add = { param($element) [void]$Panel.Children.Add($element) }
    & $add (New-HcVisitToggle)
    & $add (New-HcText (T 'mem.title') 22 'Text' -Bold -Margin @(0, 4, 0, 10))
    if ($h.Notice) { & $add (New-HcText $h.Notice 14.5 'Ok' -Bold) }
    switch ($h.Stage) {
        'offline' { & $add (New-HcText (T 'win.hist.offline') 15 'Soft') }
        'code'    { & $add (New-HcCodeBox 'history' (T 'win.hist.codeIntro')) }
        'loading' {
            & $add (New-HcText (T 'win.fin.loading') 15 'Soft')
            $bar = New-Object Windows.Controls.ProgressBar
            $bar.IsIndeterminate = $true
            $bar.Height = 6
            $bar.MaxWidth = 400
            $bar.HorizontalAlignment = 'Left'
            $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
            & $add $bar
        }
        'list' {
            if (@($h.Visits).Count -eq 0 -and @($h.Docs).Count -eq 0) { & $add (New-HcText (T 'mem.none') 15 'Soft'); return }
            foreach ($v in @($h.Visits)) {
                $card = New-Object Windows.Controls.StackPanel
                $head = New-Object Windows.Controls.DockPanel
                $delete = New-HcChip (T 'win.hist.delete') @{ Do = 'histDelete'; Id = [long]$v.id }
                [Windows.Controls.DockPanel]::SetDock($delete, 'Right')
                [void]$head.Children.Add($delete)
                $title = Format-HcVisitLine $v
                if ($v.label) { $title += '  ' + [char]0x00B7 + '  ' + $v.label }
                [void]$head.Children.Add((New-HcText $title 16 'Text' -Bold -Margin @(0, 4, 0, 4)))
                [void]$card.Children.Add($head)
                if ($v.invoice_number) { [void]$card.Children.Add((New-HcText (T 'mem.invoice' $v.invoice_number) 13.5 'Hi' -Bold -Margin @(0, 0, 0, 4))) }
                foreach ($p in @($v.problems)) { [void]$card.Children.Add((New-HcText ($p.code + '  ' + (T "problem.$($p.code)")) 14 'Soft' -Margin @(0, 0, 0, 2))) }
                foreach ($c in @($v.changes)) { [void]$card.Children.Add((New-HcLine 'ok' $c)) }
                foreach ($d in @($h.Docs | Where-Object { $_.visit_id -and [long]$_.visit_id -eq [long]$v.id })) { [void]$card.Children.Add((New-HcDocRow $d)) }
                if ($h.Confirm -eq [long]$v.id) {
                    [void]$card.Children.Add((New-HcQuestion (T 'win.hist.deleteAsk' (Format-HcVisitLine $v)) 'histYes' 'histNo'))
                }
                $box = New-HcBox '' @($card) 'Panel'
                $box.Padding = New-HcThickness @(16, 12, 12, 8)
                & $add $box
            }
            # Kept documents whose visit is not among these (an older one, or one never saved).
            $shown = @($h.Visits | ForEach-Object { [long]$_.id })
            $other = @($h.Docs | Where-Object { -not $_.visit_id -or [long]$_.visit_id -notin $shown })
            if ($other.Count) {
                $card = New-Object Windows.Controls.StackPanel
                [void]$card.Children.Add((New-HcText (T 'doc.other') 16 'Text' -Bold -Margin @(0, 4, 0, 4)))
                foreach ($d in $other) { [void]$card.Children.Add((New-HcDocRow $d -WithDate)) }
                $box = New-HcBox '' @($card) 'Panel'
                $box.Padding = New-HcThickness @(16, 12, 12, 8)
                & $add $box
            }
        }
    }
}

# One kept document in the history: what it is, and Openen.
function New-HcDocRow {
    param($Doc, [switch]$WithDate)
    $row = New-Object Windows.Controls.DockPanel
    $row.Margin = New-HcThickness @(0, 4, 0, 0)
    $open = New-HcChip (T 'doc.open') @{ Do = 'histDoc'; Id = [string]$Doc.id }
    [Windows.Controls.DockPanel]::SetDock($open, 'Right')
    [void]$row.Children.Add($open)
    $text = Format-HcDocLine $Doc
    if ($WithDate -and $Doc.created_at) {
        $when = Format-HcDate ([datetime]::Parse([string]$Doc.created_at, [Globalization.CultureInfo]::InvariantCulture).ToLocalTime())
        $text = $when + '  ' + [char]0x00B7 + '  ' + $text
    }
    [void]$row.Children.Add((New-HcText $text 14 'Hi' -Bold -Margin @(0, 4, 0, 4)))
    $row
}

# ==================================================== src\window-pc.ps1 ==
<#
    The window's Pc-overzicht tab (phase 6, step 3): cards for this PC,
    Windows, memory, storage and the battery, and the advice under them.
    Read-only: the facts come from the worker (Get-HcOverviewFacts), the
    rules are the pure ones in src\checks\overview.ps1. A piece of advice
    can go on the note or invoice with one click ($script:HcAdvice).
#>

function Start-HcPcLoad {
    $p = $script:HcWin.Pc
    $p.Stage = 'loading'
    Add-HcJob @{ Kind = 'overview'; Done = 'Complete-HcPcLoad' }
}

function Complete-HcPcLoad {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $p = $script:HcWin.Pc
    $facts = @($Output | Where-Object { $_ -and $_.PSObject.Properties['Disks'] }) | Select-Object -Last 1
    if ($ErrorText -or -not $facts) {
        $p.Stage = 'error'
        $p.Error = $(if ($ErrorText) { $ErrorText } else { '-' })
    } else {
        $p.Facts = $facts
        $p.Advice = @(Get-HcOverviewAdvice $facts)
        $p.Stage = 'ready'
    }
    Update-HcOther
}

# A card: a title, then its lines.
function New-HcCard {
    param([string]$Title, [object[]]$Children)
    $stack = New-Object Windows.Controls.StackPanel
    [void]$stack.Children.Add((New-HcText $Title.ToUpperInvariant() 12 'Soft' -Bold -Margin @(0, 0, 0, 8)))
    foreach ($c in $Children) { if ($c) { [void]$stack.Children.Add($c) } }
    $card = New-Object Windows.Controls.Border
    $card.Width = 300
    $card.CornerRadius = New-Object Windows.CornerRadius(12)
    $card.BorderThickness = New-HcThickness @(1, 1, 1, 1)
    $card.Padding = New-HcThickness @(16, 14, 16, 10)
    $card.Margin = New-HcThickness @(0, 0, 14, 14)
    $card.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, 'Panel')
    $card.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'Line')
    $card.Child = $stack
    $card
}

function New-HcBar {
    param([double]$Percent, [string]$Brush = 'Hi')
    $bar = New-Object Windows.Controls.ProgressBar
    $bar.Minimum = 0
    $bar.Maximum = 100
    $bar.Value = [Math]::Max(0, [Math]::Min(100, $Percent))
    $bar.Height = 8
    $bar.BorderThickness = New-HcThickness @(0, 0, 0, 0)
    $bar.Margin = New-HcThickness @(0, 2, 0, 4)
    $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, $Brush)
    $bar.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'Line')
    $bar
}

function Update-HcPcPanel {
    param($Panel)
    $w = $script:HcWin
    $p = $w.Pc
    $add = { param($element) [void]$Panel.Children.Add($element) }
    $head = New-Object Windows.Controls.DockPanel
    $head.Margin = New-HcThickness @(0, 0, 0, 14)
    $refresh = New-HcButton (T 'pc.refresh') @{ Do = 'pcRefresh' }
    $refresh.IsEnabled = $p.Stage -ne 'loading' -and -not (Test-HcBusy)
    [Windows.Controls.DockPanel]::SetDock($refresh, 'Right')
    [void]$head.Children.Add($refresh)
    [void]$head.Children.Add((New-HcText (T 'pc.readOnly') 15 'Soft' -Margin @(0, 8, 0, 0)))
    & $add $head

    if ($p.Stage -eq 'new') { Start-HcPcLoad }
    switch ($p.Stage) {
        'loading' {
            & $add (New-HcText (T 'pc.loading') 15 'Soft')
            $bar = New-Object Windows.Controls.ProgressBar
            $bar.IsIndeterminate = $true
            $bar.Height = 6
            $bar.MaxWidth = 400
            $bar.HorizontalAlignment = 'Left'
            $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
            & $add $bar
            return
        }
        'error' { & $add (New-HcText (T 'pc.error' $p.Error) 15 'Warn' -Bold); return }
    }
    $f = $p.Facts
    $today = Get-Date
    $cards = New-Object Windows.Controls.WrapPanel

    # This PC.
    $lines = @((New-HcText $f.Name 17 'Text' -Bold -Margin @(0, 0, 0, 4)))
    $lines += New-HcText $(if ($f.Laptop) { T 'pc.laptop' } else { T 'pc.desktop' }) 14 'Soft'
    $lines += New-HcText $f.Cpu 14.5 'Text' -Margin @(0, 0, 0, 2)
    $year = Get-HcCpuYear $f.Cpu
    $lines += New-HcText $(if ($year) { T 'pc.cpuYear' $year $f.Cores } else { T 'pc.cpuCores' $f.Cores }) 13.5 'Soft'
    foreach ($g in @($f.Gpus)) { $lines += New-HcText (T 'pc.gpu' $g) 13.5 'Soft' -Margin @(0, 0, 0, 2) }
    [void]$cards.Children.Add((New-HcCard (T 'pc.card.pc') $lines))

    # Windows, and until when it gets updates.
    $support = Get-HcWindowsSupport $f.Build $f.DisplayVersion $f.Edition $today
    $lines = @((New-HcText (($f.Os + ' ' + $f.DisplayVersion).Trim()) 16 'Text' -Bold))
    if (-not $support) {
        $lines += New-HcLine 'skipped' (T 'pc.win.unknown')
    } elseif ($support.Major -eq 10) {
        $lines += New-HcLine 'problem' (T 'pc.win10' (Format-HcLongDate $support.End))
        $lines += New-HcLine $(if ($today -lt $support.Esu) { 'warn' } else { 'problem' }) (T 'pc.win10Esu' (Format-HcLongDate $support.Esu))
        $cpuOk = Test-HcCpuWin11 $f.Cpu
        $lines += New-HcLine $(if ($cpuOk -eq $true) { 'ok' } elseif ($cpuOk -eq $false) { 'problem' } else { 'skipped' }) (T "pc.win11Cpu.$(if ($null -eq $cpuOk) { 'unknown' } else { "$cpuOk".ToLower() })")
    } else {
        $status = @{ ok = 'ok'; soon = 'warn'; ended = 'problem' }[$support.Status]
        $lines += New-HcLine $status (T "pc.win.$($support.Status)" (Format-HcLongDate $support.End))
    }
    [void]$cards.Children.Add((New-HcCard 'Windows' $lines))

    # Memory.
    $lines = @((New-HcText ((T 'pc.ram' ([Math]::Round($f.RamGB)) "$($f.RamType)")).Trim() 16 'Text' -Bold))
    if ($f.SlotsTotal -gt 0) { $lines += New-HcText (T 'pc.slots' $f.SlotsUsed $f.SlotsTotal) 13.5 'Soft' }
    $lines += New-HcLine $(if ($f.RamGB -ge 7.5) { 'ok' } else { 'warn' }) $(if ($f.RamGB -ge 7.5) { T 'pc.ramOk' } else { T 'pc.ramLow' })
    [void]$cards.Children.Add((New-HcCard (T 'pc.card.ram') $lines))

    # Storage: every disk, and how full the one with Windows is.
    $lines = @()
    foreach ($d in @($f.Disks)) {
        $lines += New-HcText ((Format-HcSize $d.SizeGB) + ' ' + (T "pc.kind.$($d.Kind)") + $(if ($d.Bus -eq 'NVMe') { ' (NVMe)' } else { '' })) 15 'Text' -Bold -Margin @(0, 4, 0, 0)
        $lines += New-HcText $d.Name 12.5 'Soft' -Margin @(0, 0, 0, 2)
        if ($d.Number -eq $f.SystemDisk -and $f.SystemSizeGB -gt 0) {
            $used = 100 * (1 - $f.SystemFreeGB / $f.SystemSizeGB)
            $lines += New-HcText (T 'pc.systemDisk') 13.5 'Text'
            $lines += New-HcBar $used $(if ($used -ge 90) { 'Warn' } else { 'Hi' })
            $lines += New-HcText (T 'pc.free' ([Math]::Round($f.SystemFreeGB)) ([Math]::Round($f.SystemSizeGB))) 13 'Soft'
        }
        $lines += New-HcLine $(if ($d.Health -eq 'Healthy') { 'ok' } elseif ($d.Health) { 'problem' } else { 'skipped' }) $(if ($d.Health -eq 'Healthy') { T 'pc.healthOk' } else { T 'pc.healthBad' $d.Health })
    }
    if (-not $lines.Count) { $lines = @(New-HcLine 'skipped' (T 'pc.noDisks')) }
    [void]$cards.Children.Add((New-HcCard (T 'pc.card.disk') $lines))

    # The battery, on a laptop.
    if ($f.HasBattery) {
        $lines = if ($f.BatteryHealth) {
            @((New-HcText "$($f.BatteryHealth)%" 20 'Text' -Bold), (New-HcBar $f.BatteryHealth $(if ($f.BatteryHealth -lt 70) { 'Warn' } else { 'Ok' })), (New-HcText (T 'pc.battery' $f.BatteryHealth) 13.5 'Soft'))
        } else { @(New-HcLine 'skipped' (T 'pc.noBatteryInfo')) }
        [void]$cards.Children.Add((New-HcCard (T 'pc.card.battery') $lines))
    }
    & $add $cards

    # The advice.
    & $add (New-HcText (T 'pc.advice') 20 'Text' -Bold -Margin @(0, 6, 0, 10))
    foreach ($a in @($p.Advice)) {
        $short = Get-HcAdviceText $a '.short'
        $stack = New-Object Windows.Controls.StackPanel
        $status = @{ problem = 'problem'; warn = 'warn'; upgrade = 'tip'; info = 'info'; ok = 'ok' }[$a.Level]
        [void]$stack.Children.Add((New-HcLine $status (Get-HcAdviceText $a '.title') 'Text'))
        $body = New-HcText (Get-HcAdviceText $a) 14.5 'Text' -Margin @(36, 0, 0, 8)
        [void]$stack.Children.Add($body)
        $buttons = New-Object Windows.Controls.WrapPanel
        $buttons.Margin = New-HcThickness @(36, 0, 0, 0)
        if ($a.Level -ne 'ok') {
            $on = $script:HcAdvice -contains $short
            $label = if ($on) { [string][char]0x2713 + ' ' + (T 'pc.onNoteDone') } else { T 'pc.onNote' }
            [void]$buttons.Children.Add((New-HcChip $label @{ Do = 'adviceNote'; Text = $short } -On:$on))
        }
        if ($a.Code) { [void]$buttons.Children.Add((New-HcChip ((T 'win.open' $a.Code) + '  ' + (T "problem.$($a.Code)")) @{ Do = 'problem'; Code = $a.Code })) }
        if ($buttons.Children.Count) { [void]$stack.Children.Add($buttons) }
        $box = New-HcBox '' @($stack) $(if ($a.Level -in @('problem', 'upgrade')) { 'HiSoft' } else { 'Panel' })
        $box.Padding = New-HcThickness @(14, 12, 14, 6)
        $box.MaxWidth = 940
        $box.HorizontalAlignment = 'Left'
        & $add $box
    }
}

# One piece of advice in words: its sentence, or with a suffix its .title or .short.
function Get-HcAdviceText {
    param([pscustomobject]$Advice, [string]$Suffix = '')
    $all = @("adv.$($Advice.Id)$Suffix") + @($Advice.Args)
    T @all
}

function Invoke-HcPcClick {
    param([hashtable]$Tag)
    $w = $script:HcWin
    switch ($Tag.Do) {
        'pcRefresh' { if (-not (Test-HcBusy)) { $w.Pc.Stage = 'new'; Update-HcOther } }
        'adviceNote' {
            if ($script:HcAdvice -contains $Tag.Text) { $script:HcAdvice.Remove($Tag.Text) } else { [void]$script:HcAdvice.Add($Tag.Text) }
            Update-HcOther
        }
        default { return $false }
    }
    $true
}

# ==================================================== src\window-phone.ps1 ==
<#
    The window's "Telefoon & tablet" tab (6 Oct, layout A of the mockup at
    https://claude.ai/artifact/DAQnEZNLsMhEY1s9p8orZx, chosen by Shamil):
    the devices on the left, the chosen device in the middle (its tools,
    four figures, the checks M2-M7 as tiles), and a check's result on the
    right, in the same result view as Problemen.

    Nothing here reads the device itself: the facts come from the worker
    (job 'phone', Get-HcPhoneFacts), the checks and fixes are area M's
    (src\checks\android.ps1), run through the window's usual jobs.
#>

# The checks shown as tiles; M1 is the device card itself, M8 the connect view.
$script:HcPhoneTiles = @('M2', 'M3', 'M4', 'M5', 'M6', 'M7')
# The tool buttons on the device card, in this order.
$script:HcPhoneTools = @('phoneMirror', 'phoneScreenshot', 'phoneRestart')

function New-HcPhoneState {
    @{ Stage = 'new'; Facts = $null; Serial = $null; Connect = $false; Ask = $null; Banner = $null
       Notice = $null; ShowSteps = $false; Error = $null; PreferWifi = $false; Pending = @{} }
}

# ---------------------------------------------------------------- loading --

function Start-HcPhoneLoad {
    $p = $script:HcWin.Ph
    $p.Stage = 'loading'
    Add-HcJob @{ Kind = 'phone'; Text = "$($p.Serial)"; Done = 'Complete-HcPhoneLoad' }
}

function Complete-HcPhoneLoad {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $p = $w.Ph
    $facts = @($Output | Where-Object { $_ -and $_.PSObject.Properties['AdbFound'] }) | Select-Object -Last 1
    if ($ErrorText -or -not $facts) {
        $p.Stage = 'error'
        $p.Error = $(if ($ErrorText) { $ErrorText } else { '-' })
        Update-HcPhone
        return
    }
    # Just paired over Wi-Fi: show that device, not a phone on the cable.
    if ($p.PreferWifi) {
        $p.PreferWifi = $false
        $wifi = @($facts.Devices | Where-Object { $_.State -eq 'device' -and (Test-HcWifiSerial $_.Serial) }) | Select-Object -First 1
        if ($wifi -and $wifi.Serial -ne $facts.Serial) { $p.Serial = $wifi.Serial; Start-HcPhoneLoad; return }
    }
    # Another device than before: its old check results no longer apply.
    if ($facts.Serial -ne $p.Serial) {
        foreach ($code in @($w.Reports.Keys | Where-Object { $_ -like 'M*' })) { $w.Reports.Remove($code) }
        if ($w.Code -like 'M*' -and $w.Code -ne 'M8') { $w.Code = $null; $w.Report = $null; $w.View = 'empty' }
    }
    $p.Facts = $facts
    $p.Serial = $facts.Serial
    $p.Stage = 'ready'
    if (-not $facts.Serial) { $p.Connect = $true }
    Update-HcPhone
    if ($w.Tab -eq 'phone') { Update-HcResult }
}

# ------------------------------------------------------------- painting --

function Update-HcPhone {
    $w = $script:HcWin
    # Only while the tab is open: its code boxes share $HcWin.Totp with Bezoek's.
    if (-not $w -or -not $w.Ph -or $w.Tab -ne 'phone') { return }
    if ($w.Ph.Stage -eq 'new') { Start-HcPhoneLoad }
    Update-HcPhoneSide
    Update-HcPhoneMain
}

# A rounded card, the way the other tabs draw them.
function New-HcPhoneCard {
    param([object[]]$Children, [string]$Background = 'Panel', [string]$Border = 'Line')
    $stack = New-Object Windows.Controls.StackPanel
    foreach ($c in $Children) { if ($c) { [void]$stack.Children.Add($c) } }
    $card = New-Object Windows.Controls.Border
    $card.CornerRadius = New-Object Windows.CornerRadius(12)
    $card.BorderThickness = New-HcThickness @(1, 1, 1, 1)
    $card.Padding = New-HcThickness @(16, 14, 16, 10)
    $card.Margin = New-HcThickness @(0, 0, 0, 14)
    $card.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, $Background)
    $card.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, $Border)
    $card.Child = $stack
    $card
}

function Update-HcPhoneSide {
    $w = $script:HcWin
    $p = $w.Ph
    $panel = $w.Window.FindName('PhoneSide')
    $panel.Children.Clear()
    $busy = Test-HcBusy
    [void]$panel.Children.Add((New-HcHeading (T 'ph.devices')))
    $devices = @()
    if ($p.Facts) { $devices = @($p.Facts.Devices) }
    if (-not $devices.Count) { [void]$panel.Children.Add((New-HcText (T 'ph.none') 14 'Soft' -Margin @(2, 0, 0, 10))) }
    foreach ($d in $devices) {
        $chosen = $p.Facts -and $d.Serial -eq $p.Facts.Serial -and -not $p.Connect
        $name = if ($chosen -and $p.Facts.Name) { $p.Facts.Name } elseif ($d.Model) { $d.Model } else { $d.Serial }
        $content = New-Object Windows.Controls.StackPanel
        [void]$content.Children.Add((New-HcText $name 15 '' -Bold -Margin @(0, 0, 0, 2)))
        $state = switch ($d.State) {
            'device'       { @(([string][char]0x25CF + ' ' + $(if (Test-HcWifiSerial $d.Serial) { T 'ph.via.wifi' } else { T 'ph.via.usb' })), 'Ok') }
            'unauthorized' { @((T 'ph.unauthorized'), 'Warn') }
            default        { @((T 'ph.offline'), 'Warn') }
        }
        [void]$content.Children.Add((New-HcText $state[0] 12.5 $state[1] -Bold -Margin @(0, 0, 0, 0)))
        $b = New-HcButton $content @{ Do = 'phSelect'; Serial = $d.Serial }
        $b.HorizontalContentAlignment = 'Left'
        $b.Margin = New-HcThickness @(0, 0, 0, 8)
        $b.IsEnabled = -not $busy -and $d.State -eq 'device'
        if ($chosen) {
            $b.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'HiSoft')
            $b.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Hi')
        }
        [void]$panel.Children.Add($b)
    }
    $connect = New-HcButton ('+  ' + (T 'ph.connect')) @{ Do = 'phConnect' } $(if ($p.Facts -and $p.Facts.Serial) { 'HcButton' } else { 'HcPrimary' })
    $connect.IsEnabled = -not $busy
    [void]$panel.Children.Add($connect)
    $again = New-HcButton (T 'ph.refresh') @{ Do = 'phRefresh' }
    $again.IsEnabled = -not $busy
    [void]$panel.Children.Add($again)
    [void]$panel.Children.Add((New-HcText (T 'ph.doneHint') 13 'Soft' -Margin @(0, 16, 0, 0)))
}

function Update-HcPhoneMain {
    $w = $script:HcWin
    $p = $w.Ph
    $panel = $w.Window.FindName('PhoneMain')
    $panel.Children.Clear()
    $add = { param($element) [void]$panel.Children.Add($element) }
    if ($p.Banner) { & $add (New-HcText $p.Banner 14.5 'Ok' -Bold) }
    if ($p.Notice) { & $add (New-HcText $p.Notice 14.5 'Warn' -Bold) }
    switch ($p.Stage) {
        { $_ -in @('new', 'loading') } {
            & $add (New-HcText (T 'ph.loading') 15 'Soft')
            $bar = New-Object Windows.Controls.ProgressBar
            $bar.IsIndeterminate = $true
            $bar.Height = 6
            $bar.MaxWidth = 400
            $bar.HorizontalAlignment = 'Left'
            $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
            & $add $bar
            return
        }
        'error' { & $add (New-HcText (T 'ph.error' $p.Error) 15 'Warn' -Bold); return }
    }
    if ($p.Connect -or -not $p.Facts.Serial) { Add-HcPhoneConnect $panel } else { Add-HcPhoneDevice $panel }
}

# No device yet, or "Toestel verbinden": the cable and Wi-Fi side by side.
function Add-HcPhoneConnect {
    param($Panel)
    $w = $script:HcWin
    $p = $w.Ph
    $f = $p.Facts
    $add = { param($element) [void]$Panel.Children.Add($element) }
    if ($f.Serial) { & $add (New-HcButton ([string][char]0x2190 + '  ' + (T 'ph.back')) @{ Do = 'phBack' }) }
    $title = New-HcText (T 'ph.connect') 24 'Text' -Bold -Margin @(0, 4, 0, 4)
    $title.FontFamily = New-Object Windows.Media.FontFamily('Georgia')
    & $add $title
    & $add (New-HcText (T 'ph.connectIntro') 14.5 'Soft' -Margin @(0, 0, 0, 14))

    # The cable: what Housecall sees on it right now, and the steps for that.
    $cable = @((New-HcText (T 'ph.cable') 18 'Text' -Bold -Margin @(0, 0, 0, 2)), (New-HcText (T 'ph.cableSub') 13 'Soft' -Margin @(0, 0, 0, 10)))
    $i = 1
    foreach ($s in @((T 'ph.cableSteps') -split '\s*\|\s*')) { $cable += New-HcText ("$i. $s") 14 'Text' -Margin @(0, 0, 0, 4); $i++ }
    $status = Test-HcPhoneOverview $f
    if (-not $f.Serial) {
        $first = @($status.Results | Where-Object { $_.Status -eq 'problem' }) | Select-Object -First 1
        $stack = @()
        if ($first) { $stack += New-HcText $first.Text 14.5 'Text' -Bold -Margin @(0, 0, 0, 4) }
        if ($status.FindingId) { $stack += New-HcText (T ('advice.' + $status.FindingId)) 13.5 'Soft' -Margin @(0, 0, 0, 8) }
        $buttons = New-Object Windows.Controls.WrapPanel
        if (-not $f.AdbFound) { [void]$buttons.Children.Add((New-HcButton (T 'ph.getAdb') @{ Do = 'phTool'; FixId = 'getAdb' } 'HcPrimary')) }
        $steps = @(Get-HcSteps $status)
        if ($steps.Count) { [void]$buttons.Children.Add((New-HcButton (T 'fix.steps') @{ Do = 'phSteps' })) }
        [void]$buttons.Children.Add((New-HcButton (T 'ph.refresh') @{ Do = 'phRefresh' }))
        foreach ($b in $buttons.Children) { $b.Margin = New-HcThickness @(0, 0, 8, 6) }
        $stack += $buttons
        if ($p.ShowSteps) {
            for ($k = 0; $k -lt $steps.Count; $k++) { $stack += New-HcText ((T 'fix.stepOf' ($k + 1) $steps.Count) + ' ' + $steps[$k]) 14 'Text' -Margin @(2, 6, 0, 2) }
        }
        if ($p.Ask) { $stack += New-HcPhoneAsk }
        $cable += New-HcBox '' $stack 'HiSoft'
    }
    $cableCard = New-HcPhoneCard $cable

    # Wi-Fi: only the 6-digit code; the address as a way out.
    $wifi = @((New-HcText (T 'ph.wifi') 18 'Text' -Bold -Margin @(0, 0, 0, 2)), (New-HcText (T 'ph.wifiSub') 13 'Soft' -Margin @(0, 0, 0, 10)))
    if ($f.AdbFound) {
        $wifi += New-HcCodeBox 'pair' (T 'ph.wifiIntro') -Label (T 'ph.pairLabel') -Hint (T 'ph.wifiNote') -GoText (T 'ph.pair')
        $wifi += New-HcButton (T 'ph.address') @{ Do = 'phAddress' }
    } else {
        $wifi += New-HcText (T 'ph.wifiNeedsAdb') 14 'Soft'
    }
    $wifiCard = New-HcPhoneCard $wifi

    # One above the other: side by side, the six code boxes do not fit.
    & $add $cableCard
    & $add $wifiCard
}

# The question under a tool: "Scherm van X tonen op deze laptop?" Ja / Nee.
function New-HcPhoneAsk {
    $p = $script:HcWin.Ph
    $label = T ('fix.' + $p.Ask) $p.Facts.Name
    New-HcQuestion (T 'win.confirm' $label) 'phToolYes' 'phToolNo'
}

# The chosen device: its card with the tools, four figures, the checks.
function Add-HcPhoneDevice {
    param($Panel)
    $w = $script:HcWin
    $p = $w.Ph
    $f = $p.Facts
    $busy = Test-HcBusy
    $add = { param($element) [void]$Panel.Children.Add($element) }
    $culture = if ($script:Lang -eq 'nl') { 'nl-NL' } else { 'en-GB' }
    $dot = '  ' + [char]0x00B7 + '  '

    # "S24 Ultra van shamil (Samsung SM-S928B)": the name big, the model under it.
    $title = $f.Name
    $sub = @()
    if ("$($f.Name)" -match '^(.+) \(([^()]+)\)$') { $title = $Matches[1]; $sub += $Matches[2] }
    $name = New-HcText $title 24 'Text' -Bold -Margin @(0, 0, 0, 2)
    $name.FontFamily = New-Object Windows.Media.FontFamily('Georgia')
    $sub += "Android $($f.Android)"
    if ($f.Patch) { $sub += T 'ph.patch' $f.Patch.ToString('MMMM yyyy', [Globalization.CultureInfo]::GetCultureInfo($culture)) }
    if ($null -ne $f.Apps) { $sub += T 'and.apps' $f.Apps }
    $tools = New-Object Windows.Controls.WrapPanel
    $tools.Margin = New-HcThickness @(0, 8, 0, 0)
    foreach ($id in $script:HcPhoneTools) {
        $b = New-HcButton (T "ph.$id") @{ Do = 'phTool'; FixId = $id } $(if ($id -eq 'phoneMirror') { 'HcPrimary' } else { 'HcButton' })
        $b.Margin = New-HcThickness @(0, 0, 8, 6)
        $b.IsEnabled = -not $busy
        [void]$tools.Children.Add($b)
    }
    $off = New-HcButton (T 'ph.phoneDebugOff') @{ Do = 'phTool'; FixId = 'phoneDebugOff' }
    $off.Margin = New-HcThickness @(0, 0, 8, 6)
    $off.IsEnabled = -not $busy
    $off.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Bad')
    [void]$tools.Children.Add($off)
    $card = @($name, (New-HcText ($sub -join $dot) 13.5 'Soft' -Margin @(0, 0, 0, 0)), $tools)
    if ($p.Ask) { $card += New-HcPhoneAsk }
    & $add (New-HcPhoneCard $card)

    # Four figures, coloured by the same limits as the checks.
    $figures = New-Object Windows.Controls.Primitives.UniformGrid
    $figures.Columns = 4
    $figures.Margin = New-HcThickness @(0, 0, 0, 6)
    foreach ($fig in @(Get-HcPhoneFigures $f)) {
        $lines = @((New-HcText $fig.Title.ToUpperInvariant() 11.5 $(if ($fig.Level -eq 'ok') { 'Soft' } else { 'Warn' }) -Bold -Margin @(0, 0, 0, 4)),
                   (New-HcText $fig.Value 15.5 'Text' -Bold -Margin @(0, 0, 0, 2)))
        if ($null -ne $fig.Bar) { $lines += New-HcBar $fig.Bar $(if ($fig.Level -eq 'ok') { 'Ok' } else { 'Warn' }) }
        if ($fig.Note) { $lines += New-HcText $fig.Note 12.5 $(if ($fig.Level -eq 'ok') { 'Soft' } else { 'Warn' }) -Margin @(0, 0, 0, 0) }
        $c = New-HcPhoneCard $lines $(if ($fig.Level -eq 'ok') { 'Panel' } else { 'HiSoft' })
        $c.Margin = New-HcThickness @(0, 0, 8, 8)
        $c.Padding = New-HcThickness @(12, 10, 12, 8)
        [void]$figures.Children.Add($c)
    }
    & $add $figures

    # The checks as tiles: what each found, at a glance.
    $head = New-Object Windows.Controls.DockPanel
    $head.Margin = New-HcThickness @(0, 4, 0, 8)
    $all = New-HcButton (T 'ph.checkAll') @{ Do = 'phCheckAll' }
    $all.IsEnabled = -not $busy
    [Windows.Controls.DockPanel]::SetDock($all, 'Right')
    [void]$head.Children.Add($all)
    [void]$head.Children.Add((New-HcText (T 'ph.checks') 18 'Text' -Bold -Margin @(0, 4, 0, 0)))
    & $add $head
    $tiles = New-Object Windows.Controls.Primitives.UniformGrid
    $tiles.Columns = 2
    foreach ($code in $script:HcPhoneTiles) {
        $report = $w.Reports[$code]
        $content = New-Object Windows.Controls.StackPanel
        $top = New-Object Windows.Controls.StackPanel
        $top.Orientation = 'Horizontal'
        [void]$top.Children.Add((New-HcText $code 12 'Hi' -Bold -Margin @(0, 2, 8, 0)))
        [void]$top.Children.Add((New-HcText (T "ph.tile.$code") 15 '' -Bold -Margin @(0, 0, 0, 0)))
        [void]$content.Children.Add($top)
        $line = if ($p.Pending.ContainsKey($code)) { @((T 'ph.tile.busy'), 'Soft') }
                elseif (-not $report) { @((T 'ph.tile.todo'), 'Soft') }
                else {
                    $level = Get-HcReportLevel $report
                    $first = @($report.Results | Where-Object { $_.Status -eq $level }) | Select-Object -First 1
                    switch ($level) {
                        'ok'    { @(([string][char]0x2713 + ' ' + (T 'ph.tile.ok')), 'Ok') }
                        default { @(([string][char]0x25B2 + ' ' + $(if ($first) { $first.Text } else { T 'ph.tile.look' })), $(if ($level -eq 'problem') { 'Bad' } else { 'Warn' })) }
                    }
                }
        $status = New-HcText $line[0] 12.5 $line[1] -Bold -Margin @(0, 4, 0, 0)
        $status.TextTrimming = 'CharacterEllipsis'
        $status.TextWrapping = 'NoWrap'
        [void]$content.Children.Add($status)
        $b = New-HcButton $content @{ Do = 'phTile'; Code = $code }
        $b.HorizontalContentAlignment = 'Left'
        $b.Margin = New-HcThickness @(0, 0, 8, 8)
        $b.IsEnabled = -not $busy
        if ($w.Code -eq $code) {
            $b.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'HiSoft')
            $b.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Hi')
        }
        [void]$tiles.Children.Add($b)
    }
    & $add $tiles
}

<#
    Pure: the four figures on the device card, with the same limits as the
    M checks (storage, memory, battery, last restart). Level ok or warn.
#>
function Get-HcPhoneFigures {
    param([pscustomobject]$Facts)
    $f = $Facts
    $out = @()
    if ($f.DataTotalKB) {
        $pct = 100 * $f.DataFreeKB / $f.DataTotalKB
        $low = $pct -lt $script:PhoneStorageLowPercent -or ($f.DataFreeKB * 1024 / 1e9) -lt $script:PhoneStorageFullGB
        $out += [pscustomobject]@{ Title = (T 'ph.fig.storage'); Value = (T 'ph.free' (Format-HcPhoneSize $f.DataFreeKB)); Bar = (100 - $pct); Note = (T 'ph.of' (Format-HcPhoneSize $f.DataTotalKB)); Level = $(if ($low) { 'warn' } else { 'ok' }) }
    }
    if ($f.RamKB) {
        $freePct = if ($f.RamFreeKB) { 100 * $f.RamFreeKB / $f.RamKB } else { 100 }
        $low = $freePct -lt $script:PhoneMemoryFullPercent -or ($f.RamKB * 1024 / 1e9) -lt $script:PhoneLowRamGB
        $out += [pscustomobject]@{ Title = (T 'ph.fig.memory'); Value = (T 'ph.free' (Format-HcPhoneSize $f.RamFreeKB)); Bar = (100 - $freePct); Note = (T 'ph.of' (Format-HcPhoneSize $f.RamKB)); Level = $(if ($low) { 'warn' } else { 'ok' }) }
    }
    $b = $f.Battery
    if ($b -and $null -ne $b.Level) {
        $state = switch ($b.Status) { 2 { 'charging' } 5 { 'full' } 4 { 'notCharging' } default { if ($b.Plugged) { 'plugged' } else { 'onBattery' } } }
        $bad = ($b.Health -in 3..6) -or ($null -ne $b.TempC -and $b.TempC -ge $script:PhoneHotCelsius) -or ($b.Plugged -and $state -eq 'notCharging' -and $b.Level -lt 95)
        $note = @()
        if ($null -ne $b.Health) { $note += T $(if ($b.Health -in 2..7) { "and.health.$($b.Health)" } else { 'and.health.1' }) }
        if ($null -ne $b.TempC) { $note += T 'ph.degrees' ("$($b.TempC)" -replace '\.', $(if ($script:Lang -eq 'nl') { ',' } else { '.' })) }
        $out += [pscustomobject]@{ Title = (T 'ph.fig.battery'); Value = ("$($b.Level)%, " + (T "and.bat.$state")); Bar = $b.Level; Note = ($note -join ', '); Level = $(if ($bad) { 'warn' } else { 'ok' }) }
    }
    if ($null -ne $f.UptimeSec) {
        $days = [int][Math]::Floor($f.UptimeSec / 86400)
        $long = $days -ge $script:PhoneUptimeDays
        $out += [pscustomobject]@{ Title = (T 'ph.fig.restart'); Value = (T 'ph.daysAgo' $days); Bar = $null; Note = $(if ($long) { T 'ph.restartAdvice' } else { '' }); Level = $(if ($long) { 'warn' } else { 'ok' }) }
    }
    $out
}

# ---------------------------------------------------------------- doing --

function Invoke-HcPhoneClick {
    param([hashtable]$Tag)
    $w = $script:HcWin
    $p = $w.Ph
    switch ($Tag.Do) {
        'phSelect'  { if (-not (Test-HcBusy)) { Clear-HcPhoneMessages; $p.Connect = $false; $p.Serial = $Tag.Serial; Start-HcPhoneLoad; Update-HcPhone } }
        'phRefresh' { if (-not (Test-HcBusy)) { Clear-HcPhoneMessages; Start-HcPhoneLoad; Update-HcPhone } }
        'phConnect' { Clear-HcPhoneMessages; $p.Connect = $true; Update-HcPhone }
        'phBack'    { Clear-HcPhoneMessages; $p.Connect = $false; Update-HcPhone }
        'phSteps'   { $p.ShowSteps = -not $p.ShowSteps; Update-HcPhone }
        'phAddress' {
            # Typing the address: the same input view as A3, on the right.
            $w.Code = 'M8'; $w.Input = $w.Inputs['M8']; $w.View = 'input'; Clear-HcMessages; Update-HcResult
        }
        'phTool'    { $p.Ask = $Tag.FixId; $p.Banner = $null; $p.Notice = $null; Update-HcPhone }
        'phToolNo'  { $p.Ask = $null; $p.Notice = T 'fix.cancelled'; Update-HcPhone }
        'phToolYes' { Invoke-HcPhoneTool }
        'phTile'    {
            if (Test-HcBusy) { return $true }
            $report = $w.Reports[$Tag.Code]
            if ($report) {
                # Checked already: show it; "check again" is one click on the right.
                $w.Code = $Tag.Code; $w.Report = $report; $w.View = 'report'; $w.FromAll = $false
                Clear-HcMessages
                $script:HcCurrentCode = $Tag.Code
                Update-HcResult
                Update-HcPhone
            } else {
                Open-HcProblem $Tag.Code
            }
        }
        'phCheckAll' { Start-HcPhoneCheckAll }
        default     { return $false }
    }
    $true
}

function Clear-HcPhoneMessages {
    $p = $script:HcWin.Ph
    $p.Ask = $null
    $p.Banner = $null
    $p.Notice = $null
    $p.ShowSteps = $false
}

# A tool, confirmed: run its fix on the worker like any other.
function Invoke-HcPhoneTool {
    $w = $script:HcWin
    $p = $w.Ph
    $id = $p.Ask
    $p.Ask = $null
    if (-not $id -or (Test-HcBusy)) { return }
    if ($script:DryRun) { $p.Notice = T 'fix.dryRun'; Update-HcPhone; return }
    $name = if ($p.Facts.Name) { $p.Facts.Name } else { $p.Facts.Serial }
    $p.Banner = (T ('fix.' + $id) $name) + '...'
    Add-HcJob @{ Kind = 'fix'; FixId = $id; Target = @{ Serial = $p.Facts.Serial; Label = $name }; Done = 'Complete-HcPhoneTool' }
    Update-HcPhone
    Update-HcSide
}

function Complete-HcPhoneTool {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $p = $w.Ph
    if ($ErrorText) {
        $p.Banner = $null
        $p.Notice = T 'fix.failed' $ErrorText
        Update-HcPhone
        return
    }
    $done = T ('fix.' + $Job.FixId + '.done') $Job.Target.Label
    if (-not $script:Fixes[$Job.FixId].NoLog) {
        [void](Add-HcChange $Job.FixId $Job.Target $done)
    }
    $p.Banner = [string][char]0x2713 + ' ' + $done
    # These change what is connected: read the devices again.
    if ($Job.FixId -in @('phoneRestart', 'phoneDebugOff', 'getAdb')) { Start-HcPhoneLoad }
    Update-HcPhone
    Update-HcSide
}

# "Alles controleren" for the device: M2-M7, each straight onto its tile.
function Start-HcPhoneCheckAll {
    $w = $script:HcWin
    $p = $w.Ph
    if ((Test-HcBusy) -or -not $p.Serial) { return }
    foreach ($code in $script:HcPhoneTiles) {
        $p.Pending[$code] = $true
        Add-HcJob @{ Kind = 'check'; Code = $code; Text = $p.Serial; Done = 'Complete-HcPhoneCheckItem' }
    }
    Update-HcPhone
}

function Complete-HcPhoneCheckItem {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $p = $w.Ph
    $p.Pending.Remove($Job.Code)
    $report = Get-HcJobReport $Output
    if ($report -and -not $ErrorText) {
        $w.Reports[$Job.Code] = $report
        $w.Inputs[$Job.Code] = $Job.Text
        if ((Get-HcReportLevel $report) -ne 'ok') { Save-HcVisit $Job.Code $report }
    }
    Update-HcPhone
}

# The 6-digit pairing code, from the code boxes: M8 with only the code.
function Submit-HcPairCode {
    param([string]$Code)
    $w = $script:HcWin
    $w.Code = 'M8'
    $w.Ph.PreferWifi = $true
    Clear-HcMessages
    Start-HcWindowCheck 'M8' $Code
}

# ==================================================== src\window-start.ps1 ==
<#
    The window's Start tab (6 Oct, layout A of
    https://claude.ai/artifact/SmkY8P7PSzrzcRfHr1k6TH, chosen by Shamil):
    the first thing he sees at a client's.

      left    what Housecall already sees on this PC (the Pc-overzicht's own
              facts and advice, the ones needing attention first) and the
              last visit to this PC (after the Authenticator code)
      right   "what is the client troubled by?": the problem search and six
              quick buttons, then Alles controleren, Telefoon verbinden and
              Briefje / factuur

    Read-only like the Pc-overzicht: it shares that tab's facts ($HcWin.Pc)
    and the visit history ($HcWin.Hist), loading them when they are not there.
#>

# The quick buttons: what older clients call about most.
$script:HcStartQuick = @('A1', 'D1', 'C1', 'B1', 'F2', 'E1')

function Update-HcStartPanel {
    param($Panel)
    $w = $script:HcWin
    $add = { param($element) [void]$Panel.Children.Add($element) }
    if ($w.Pc.Stage -eq 'new') { Start-HcPcLoad }
    if ((Test-HcUnlocked) -and $w.Hist.Stage -eq 'new') { Start-HcHistoryLoad }

    # Goedemiddag, het bezoek is gestart om 14:05.
    $hour = (Get-Date).Hour
    $part = if ($hour -lt 12) { 'morning' } elseif ($hour -lt 18) { 'afternoon' } else { 'evening' }
    $title = New-HcText (T "start.hello.$part" $script:HcStartedAt.ToString('HH:mm')) 26 'Text' -Bold -Margin @(0, 0, 0, 2)
    $title.FontFamily = New-Object Windows.Media.FontFamily('Georgia')
    & $add $title
    $changed = $script:HcChangeLog.Count
    & $add (New-HcText $(if ($changed) { T 'start.changed' $changed } else { T 'start.nothingYet' }) 14.5 'Soft' -Margin @(0, 0, 0, 16))

    $grid = New-Object Windows.Controls.Grid
    foreach ($share in @(1.25, 1)) {
        $col = New-Object Windows.Controls.ColumnDefinition
        $col.Width = New-Object Windows.GridLength($share, 'Star')
        [void]$grid.ColumnDefinitions.Add($col)
    }
    $left = New-Object Windows.Controls.StackPanel
    $left.Margin = New-HcThickness @(0, 0, 10, 0)
    $right = New-Object Windows.Controls.StackPanel
    $right.Margin = New-HcThickness @(10, 0, 0, 0)
    [Windows.Controls.Grid]::SetColumn($right, 1)
    [void]$grid.Children.Add($left)
    [void]$grid.Children.Add($right)

    [void]$left.Children.Add((New-HcStartPcCard))
    [void]$left.Children.Add((New-HcStartHistoryCard))
    [void]$right.Children.Add((New-HcStartAskCard))
    foreach ($b in @(New-HcStartActions)) { [void]$right.Children.Add($b) }
    & $add $grid
}

# A card with a heading and, on the right, a link-like button to its tab.
function New-HcStartCard {
    param([string]$Title, [hashtable]$LinkTag, [string]$LinkText, [object[]]$Children)
    $head = New-Object Windows.Controls.DockPanel
    $head.Margin = New-HcThickness @(0, 0, 0, 8)
    if ($LinkTag) {
        $link = New-HcButton $LinkText $LinkTag
        $link.Padding = New-HcThickness @(10, 3, 10, 3)
        [Windows.Controls.DockPanel]::SetDock($link, 'Right')
        [void]$head.Children.Add($link)
    }
    [void]$head.Children.Add((New-HcText $Title 18 'Text' -Bold -Margin @(0, 2, 0, 0)))
    $card = New-HcPhoneCard (@($head) + @($Children))
    $card.Padding = New-HcThickness @(18, 14, 18, 12)
    $card
}

# What Housecall already sees on this PC: what it is, and what needs attention.
function New-HcStartPcCard {
    $w = $script:HcWin
    $p = $w.Pc
    $lines = @()
    switch ($p.Stage) {
        { $_ -in @('new', 'loading') } { $lines += New-HcText (T 'pc.loading') 14.5 'Soft' }
        'error' { $lines += New-HcText (T 'pc.error' $p.Error) 14.5 'Warn' }
        default {
            $f = $p.Facts
            $lines += New-HcText $f.Name 16 'Text' -Bold -Margin @(0, 0, 0, 2)
            $lines += New-HcText (Get-HcStartPcLine $f) 13.5 'Soft' -Margin @(0, 0, 0, 10)
            $important = @($p.Advice | Where-Object { $_.Level -in @('problem', 'warn', 'upgrade') } | Select-Object -First 3)
            foreach ($a in $important) {
                $status = @{ problem = 'problem'; warn = 'warn'; upgrade = 'tip' }[$a.Level]
                $lines += New-HcLine $status (Get-HcAdviceText $a '.title')
            }
            $lines += New-HcLine 'ok' $(if ($w.Environment.Online) { T 'start.online' } else { T 'start.offline' })
            if (-not $important.Count) { $lines += New-HcLine 'ok' (T 'start.pcFine') }
        }
    }
    New-HcStartCard (T 'start.thisPc') @{ Do = 'tab'; Tab = 'pc' } (T 'win.tab.pc') $lines
}

# Pure: "AMD Ryzen 7 5800X (2020), 32 GB, 2 TB SSD, Windows 11 Home 25H2",
# joined by middle dots.
function Get-HcStartPcLine {
    param([pscustomobject]$Facts)
    $f = $Facts
    $parts = @()
    if ($f.Cpu) {
        $year = Get-HcCpuYear $f.Cpu
        $parts += $(if ($year) { "$($f.Cpu) ($year)" } else { $f.Cpu })
    }
    if ($f.RamGB) { $parts += "$([Math]::Round($f.RamGB)) GB" }
    $system = @($f.Disks | Where-Object { $_.Number -eq $f.SystemDisk }) | Select-Object -First 1
    if ($system) { $parts += ((Format-HcSize $system.SizeGB) + ' ' + (T "pc.kind.$($system.Kind)")) }
    $windows = ("$($f.Os) $($f.DisplayVersion)").Trim()
    if ($windows) { $parts += $windows }
    $parts -join ('  ' + [char]0x00B7 + '  ')
}

# The last visit to this PC, from the history behind the Authenticator code.
function New-HcStartHistoryCard {
    $w = $script:HcWin
    $h = $w.Hist
    $lines = @()
    if (-not (Test-HcUnlocked)) {
        $lines += New-HcText (T 'start.historyLocked') 14 'Soft' -Margin @(0, 0, 0, 8)
        $open = New-HcButton (T 'start.historyOpen') @{ Do = 'visitView'; View = 'history' }
        $open.HorizontalAlignment = 'Left'
        $lines += $open
    } elseif ($h.Stage -in @('new', 'loading')) {
        $lines += New-HcText (T 'start.historyLoading') 14 'Soft'
    } elseif (-not @($h.Visits).Count) {
        $lines += New-HcText (T 'start.historyNone') 14 'Soft'
    } else {
        $v = @($h.Visits)[0]
        $when = Format-HcDate ([datetime]::Parse([string]$v.visited_at, [Globalization.CultureInfo]::InvariantCulture).ToLocalTime())
        $who = @($when)
        if ($v.label) { $who += [string]$v.label }
        if ($v.invoice_number) { $who += T 'mem.invoice' $v.invoice_number }
        $lines += New-HcText ($who -join ('  ' + [char]0x00B7 + '  ')) 14.5 'Text' -Bold -Margin @(0, 0, 0, 4)
        foreach ($p in @($v.problems | Select-Object -First 3)) { $lines += New-HcText ("$($p.code)  " + (T "problem.$($p.code)")) 13.5 'Soft' -Margin @(0, 0, 0, 2) }
        foreach ($c in @($v.changes | Select-Object -First 2)) { $lines += New-HcText ([string][char]0x2713 + ' ' + $c) 13.5 'Soft' -Margin @(0, 0, 0, 2) }
    }
    New-HcStartCard (T 'start.history') @{ Do = 'visitView'; View = 'history' } (T 'start.historyAll') $lines
}

# "Waar heeft de klant last van?": the problem search and six quick buttons.
function New-HcStartAskCard {
    $w = $script:HcWin
    $lines = @()
    $lines += New-HcText (T 'start.searchLabel') 13 'Soft' -Margin @(0, 0, 0, 4)
    $box = New-Object Windows.Controls.TextBox
    $box.FontSize = 15
    $box.Padding = New-HcThickness @(8, 6, 8, 6)
    $box.Margin = New-HcThickness @(0, 0, 0, 10)
    $box.SetResourceReference([Windows.Controls.Control]::BackgroundProperty, 'Bg')
    $box.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Text')
    $box.SetResourceReference([Windows.Controls.Control]::BorderBrushProperty, 'Line')
    $box.SetResourceReference([Windows.Controls.TextBox]::CaretBrushProperty, 'Hi')
    [Windows.Automation.AutomationProperties]::SetName($box, (T 'start.searchLabel'))
    # Enter: the same search in Problemen, with what was typed.
    $box.Add_KeyDown({ if ($_.Key -eq 'Return') { $_.Handled = $true; Submit-HcStartSearch $this.Text } })
    $lines += $box
    $quick = New-Object Windows.Controls.Primitives.UniformGrid
    $quick.Columns = 2
    foreach ($code in $script:HcStartQuick) {
        $content = New-Object Windows.Controls.StackPanel
        $content.Orientation = 'Horizontal'
        [void]$content.Children.Add((New-HcText $code 12 'Hi' -Bold -Margin @(0, 2, 8, 0)))
        [void]$content.Children.Add((New-HcText (T "start.quick.$code") 14.5 '' -Margin @(0, 0, 0, 0)))
        $b = New-HcButton $content @{ Do = 'problem'; Code = $code }
        $b.HorizontalContentAlignment = 'Left'
        $b.Margin = New-HcThickness @(0, 0, 8, 8)
        [void]$quick.Children.Add($b)
    }
    $lines += $quick
    New-HcStartCard (T 'start.ask') $null '' $lines
}

# The three big buttons: check everything, a phone, the note or invoice.
function New-HcStartActions {
    $busy = Test-HcBusy
    $all = New-Object Windows.Controls.StackPanel
    [void]$all.Children.Add((New-HcText (T 'win.checkAll') 16.5 '' -Bold -Margin @(0, 0, 0, 2)))
    $sub = New-HcText (T 'start.checkAllSub' @(Get-HcCheckAllCodes).Count) 13 '' -Margin @(0, 0, 0, 0)
    $sub.Opacity = 0.85
    [void]$all.Children.Add($sub)
    $big = New-HcButton $all @{ Do = 'checkAll' } 'HcPrimary'
    $big.HorizontalContentAlignment = 'Left'
    $big.Margin = New-HcThickness @(0, 4, 0, 10)
    $big.IsEnabled = -not $busy
    $big

    $row = New-Object Windows.Controls.Primitives.UniformGrid
    $row.Columns = 2
    $phone = New-HcButton (T 'start.phone') @{ Do = 'tab'; Tab = 'phone' }
    $phone.Margin = New-HcThickness @(0, 0, 8, 0)
    $note = New-HcButton (T 'win.noteInvoice') @{ Do = 'visitView'; View = 'finish' }
    $note.Margin = New-HcThickness @(0, 0, 0, 0)
    foreach ($b in @($phone, $note)) { $b.IsEnabled = -not $busy; [void]$row.Children.Add($b) }
    $row
}

# Enter in the start search: Problemen, with the same words in its search.
function Submit-HcStartSearch {
    param([string]$Text)
    $w = $script:HcWin
    $w.Tab = 'problems'
    Update-HcTabs
    Update-HcResult
    $box = $w.Window.FindName('ProblemSearch')
    $box.Text = "$Text".Trim()
    [void]$box.Focus()
    $box.CaretIndex = $box.Text.Length
}

# ==================================================== src\window-ai.ps1 ==
<#
    The window's AI-hulp tab (phase 6, step 4): the problem in the client's
    own words, and Claude picks which checks to run -- the ? of the text
    menu. The whole conversation (Invoke-HcAiConversation, src\ai.ps1) runs
    in the worker, checks included; the tab shows which check the AI is
    running while it works, then its answer. The fixes it names open in
    Problemen, through the same Ja/Nee, check again and undo as always.
#>

function New-HcAiState {
    @{ Stage = 'new'; Question = ''; Progress = @(); State = $null; Error = $null; Box = $null }
}

function Start-HcAi {
    $w = $script:HcWin
    $a = $w.Ai
    if ($a.Stage -ne 'new') { return }
    if (-not $w.Environment.Online) { $a.Stage = 'offline' }
    elseif (Test-HcUnlocked) { $a.Stage = 'ask' }
    else { $a.Stage = 'code' }
}

# The worker runs the conversation with this session's token.
function Start-HcAiQuestion {
    $w = $script:HcWin
    $a = $w.Ai
    $text = "$($a.Box.Text)".Trim()
    if (-not $text -or (Test-HcBusy)) { return }
    if (-not (Test-HcUnlocked)) { $a.Stage = 'code'; Update-HcOther; return }
    $a.Question = $text
    $a.Progress = @()
    $a.State = $null
    $a.Error = $null
    $a.Stage = 'running'
    Add-HcJob @{ Kind = 'ai'; Text = $text; Body = @{ Token = $script:HcToken; Expires = $script:HcTokenExpires }
                 Seen = 0; Live = 'Update-HcAiProgress'; Done = 'Complete-HcAi' }
    Update-HcOther
    Update-HcSide
}

# While the AI works: what it wrote so far ("De AI controleert: B1 ...").
function Update-HcAiProgress {
    param([hashtable]$Job)
    $lines = @($Job.PS.Streams.Information | ForEach-Object { "$($_.MessageData)".Trim() } | Where-Object { $_ })
    if ($lines.Count -eq $Job.Seen) { return }
    $Job.Seen = $lines.Count
    $script:HcWin.Ai.Progress = @($lines | Where-Object { $_ -ne (T 'ai.thinking') })
    if ($script:HcWin.Tab -eq 'ai') { Update-HcOther }
}

function Complete-HcAi {
    param([hashtable]$Job, [object[]]$Output, [string]$ErrorText, [string[]]$Info)
    $w = $script:HcWin
    $a = $w.Ai
    $state = @($Output | Where-Object { $_ -and $_.PSObject.Properties['Answer'] -and $_.PSObject.Properties['Reports'] }) | Select-Object -Last 1
    $a.Progress = @($Info | Where-Object { $_ -ne (T 'ai.thinking') })
    if ($ErrorText -or -not $state) {
        $a.Stage = 'answer'
        $a.Error = T 'win.error' $(if ($ErrorText) { $ErrorText } else { '-' })
    } else {
        $a.State = $state
        $a.Stage = 'answer'
        if ($state.Error) {
            if ($state.Error -eq 'locked_out') { $script:HcToken = $null }
            $a.Error = Get-HcRelayMessage $state.Error
        } elseif ($state.Refused) { $a.Error = T 'win.ai.refused' }
        # The checks the AI ran count as opened this visit, as in the text menu.
        foreach ($code in @($state.Reports.Keys)) {
            $w.Reports[$code] = $state.Reports[$code]
            if ($state.Inputs.ContainsKey($code)) { $w.Inputs[$code] = $state.Inputs[$code] }
        }
        $pick = if ($state.Answer) { [string]$state.Answer.problem_code } else { '' }
        if ($state.Reports.ContainsKey($pick)) { Save-HcVisit $pick $state.Reports[$pick] }
    }
    Update-HcOther
    Update-HcSide
}

# "Show the fixes": the report of the problem the AI points to, in
# Problemen, with only the fixes it chose (all of them after a re-check).
function Open-HcAiFixes {
    $w = $script:HcWin
    $s = $w.Ai.State
    $code = [string]$s.Answer.problem_code
    $report = $s.Reports[$code]
    if (-not $report) { return }
    Select-HcActions $report @($s.Answer.fix_ids | ForEach-Object { [string]$_ })
    $w.Tab = 'problems'
    $w.Code = $code
    $w.Report = $report
    $w.FromAll = $false
    Clear-HcMessages
    $w.View = 'report'
    $script:HcCurrentCode = $code
    Update-HcTabs
    Update-HcGroups
    Update-HcResult
}

# A chat bubble: the client's words on the right, the AI's on the left.
function New-HcBubble {
    param([object[]]$Children, [switch]$Mine)
    $stack = New-Object Windows.Controls.StackPanel
    foreach ($c in $Children) { if ($c) { [void]$stack.Children.Add($c) } }
    $b = New-Object Windows.Controls.Border
    $b.CornerRadius = New-Object Windows.CornerRadius(14)
    $b.BorderThickness = New-HcThickness @(1, 1, 1, 1)
    $b.Padding = New-HcThickness @(16, 12, 16, 8)
    $b.Margin = New-HcThickness @($(if ($Mine) { 120 } else { 0 }), 0, $(if ($Mine) { 0 } else { 80 }), 12)
    $b.HorizontalAlignment = if ($Mine) { 'Right' } else { 'Left' }
    $b.SetResourceReference([Windows.Controls.Border]::BackgroundProperty, $(if ($Mine) { 'HiSoft' } else { 'Panel' }))
    $b.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'Line')
    $b.Child = $stack
    $b
}

function Update-HcAiPanel {
    param($Panel)
    $w = $script:HcWin
    $a = $w.Ai
    $add = { param($element) [void]$Panel.Children.Add($element) }
    Start-HcAi

    switch ($a.Stage) {
        'offline' { & $add (New-HcText (T 'ai.offline') 15 'Soft'); return }
        'code'    { & $add (New-HcCodeBox 'ai' (T 'win.ai.codeIntro')); return }
    }
    & $add (New-HcText (T 'ai.privacy') 14 'Soft' -Margin @(0, 0, 0, 14))

    if ($a.Stage -eq 'ask') {
        & $add (New-HcText (T 'ai.title') 15 'Text' -Bold)
        $box = New-HcTextBox $a.Question
        $box.AcceptsReturn = $false
        $box.TextWrapping = 'Wrap'
        $box.MinHeight = 70
        $box.VerticalContentAlignment = 'Top'
        $box.Tag = @{ Do = 'aiAsk' }
        $box.Add_TextChanged({ $script:HcWin.Ai.Question = $this.Text })
        $box.Add_KeyDown({ if ($_.Key -eq 'Return') { Invoke-HcClick $this } })
        $box.Margin = New-HcThickness @(0, 4, 0, 8)
        $box.Add_Loaded({ [void]$this.Focus() })
        $a.Box = $box
        & $add $box
        $ask = New-HcButton (T 'win.ai.ask') @{ Do = 'aiAsk' } 'HcPrimary'
        $ask.HorizontalAlignment = 'Left'
        & $add $ask
        # Examples, as a client would say it: one click fills the box.
        & $add (New-HcText (T 'win.ai.examples') 13 'Soft' -Bold -Margin @(0, 14, 0, 6))
        $chips = New-Object Windows.Controls.WrapPanel
        foreach ($e in @((T 'win.ai.example') -split '\|' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) {
            [void]$chips.Children.Add((New-HcChip $e @{ Do = 'aiExample'; Text = $e }))
        }
        & $add $chips
        return
    }

    & $add (New-HcBubble @(New-HcText $a.Question 15 'Text' -Margin @(0, 0, 0, 4)) -Mine)
    $lines = @()
    foreach ($p in @($a.Progress)) { $lines += New-HcLine 'ok' $p 'Soft' }
    if ($a.Stage -eq 'running') {
        $lines += New-HcText (T 'ai.thinking') 14.5 'Soft' -Margin @(0, 4, 0, 4)
        $bar = New-Object Windows.Controls.ProgressBar
        $bar.IsIndeterminate = $true
        $bar.Height = 6
        $bar.Width = 260
        $bar.HorizontalAlignment = 'Left'
        $bar.Margin = New-HcThickness @(0, 0, 0, 6)
        $bar.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'Hi')
        $lines += $bar
        & $add (New-HcBubble $lines)
        return
    }

    # The answer.
    $s = $a.State
    if ($a.Error) {
        $lines += New-HcText $a.Error 15 'Warn' -Bold
    } elseif ($s -and $s.Answer) {
        $answer = $s.Answer
        $lines += New-HcText ([string]$answer.summary) 15.5 'Text' -Margin @(0, 4, 0, 6)
        $lines += New-HcText (T ('ai.confidence.' + $answer.confidence)) 13 'Soft'
        $steps = @($answer.steps | Where-Object { $_ })
        if ($steps.Count) {
            $lines += New-HcText (T 'ai.steps').TrimEnd(':') 14 'Text' -Bold -Margin @(0, 8, 0, 4)
            for ($i = 0; $i -lt $steps.Count; $i++) { $lines += New-HcText ("$($i + 1).  " + [string]$steps[$i]) 14.5 'Text' -Margin @(0, 0, 0, 4) }
        }
        $code = [string]$answer.problem_code
        if ($s.Reports.ContainsKey($code)) {
            $count = @($answer.fix_ids | Where-Object { $_ }).Count
            $label = if ($count) { T 'win.ai.openFixes' $code (T "problem.$code") } else { T 'win.ai.openCheck' $code (T "problem.$code") }
            $open = New-HcButton $label @{ Do = 'aiFixes' } 'HcPrimary'
            $open.Margin = New-HcThickness @(0, 8, 0, 8)
            $open.HorizontalAlignment = 'Left'
            $lines += $open
        }
    } elseif ($s -and $s.Text) {
        $lines += New-HcText ([string]$s.Text) 15 'Text'
    } else {
        $lines += New-HcText (T 'win.ai.noAnswer') 15 'Warn'
    }
    & $add (New-HcBubble $lines)
    $again = New-HcButton (T 'win.ai.again') @{ Do = 'aiAgain' }
    $again.HorizontalAlignment = 'Left'
    & $add $again
}

function Invoke-HcAiClick {
    param([hashtable]$Tag)
    $w = $script:HcWin
    switch ($Tag.Do) {
        'aiAsk'     { Start-HcAiQuestion }
        'aiExample' { $w.Ai.Box.Text = $Tag.Text; $w.Ai.Box.CaretIndex = $Tag.Text.Length; [void]$w.Ai.Box.Focus() }
        'aiFixes'   { Open-HcAiFixes }
        'aiAgain'   { $w.Ai.Stage = 'ask'; $w.Ai.Question = ''; Update-HcOther }
        default     { return $false }
    }
    $true
}

# ==================================================== src\ai.ps1 ==
<#
    The AI chat (?): the problem in the client's own words, and Claude picks
    which of Housecall's checks to run.

    The loop runs here, one relay round at a time. Claude (behind the
    relay, which holds the key and the system prompt) answers with
    run_check calls; Housecall runs those checks on this PC -- the same
    read-only checks as the menu -- and sends the results back. Claude ends
    with give_answer: a plain summary, the problem it points to, the fixes
    it recommends and manual steps.

    The AI never changes anything. The fixes it names must be ones the check
    itself offered; they go through the normal Wat nu? menu with a J/N, the
    check again as proof, and U to undo. Only the problem text and the check
    results leave the PC.

    Each turn's content is kept exactly as the API returned it (as a JSON
    string) and sent back unchanged, because Claude's thinking blocks must
    come back as they were.
#>

$script:AiMaxChecks = 6
$script:AiMaxRounds = 10

# One check by code, without asking anything: A3 and A4 take the site or
# email address the AI passes along.
function Get-HcAiCheck {
    param([string]$Code, [string]$Value)
    switch ($Code) {
        'A3'    { return New-HcSiteCheck (ConvertTo-HcHostName $Value) }
        'A4'    { return New-HcMailCheck (ConvertTo-HcMailDomain $Value) }
        default {
            $handler = $script:ProblemHandlers[$Code]
            if ($handler) { return & $handler }
            return $null
        }
    }
}

# A report as text for the AI: the lines, the finding, the advice, and the
# fixes Housecall offers, by id.
function Format-HcReportForAi {
    param([pscustomobject]$Report)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($r in $Report.Results) { $lines.Add("[$($r.Status)] $($r.Text)") }
    if ($Report.FindingId) {
        $all = @('finding.' + $Report.FindingId) + @($Report.FindingArgs)
        $lines.Add("Finding ($($Report.FindingId)): $(T @all)")
        $lines.Add("Advice: $(T ('advice.' + $Report.FindingId))")
    }
    $actions = @($Report.Actions)
    if ($actions.Count) {
        $lines.Add('Offered fixes:')
        foreach ($a in $actions) { $lines.Add("- $($a.FixId): $(Get-HcFixLabel $a)") }
    } else {
        $lines.Add('Offered fixes: none')
    }
    $lines -join "`n"
}

function ConvertTo-HcContentJson {
    param([object[]]$Blocks)
    ConvertTo-Json -InputObject @($Blocks) -Depth 20 -Compress
}

<#
    One AI conversation. Returns the answer (the give_answer input), plus
    the reports and checks it ran, so the menu can offer the fixes.
#>
function Invoke-HcAiConversation {
    param([string]$Problem)
    $history = New-Object System.Collections.ArrayList
    $first = @(@{ type = 'text'; text = "[$script:Lang]`n$Problem" })
    [void]$history.Add(@{ role = 'user'; content_json = (ConvertTo-HcContentJson $first) })

    # Inputs: the site or email address the AI passed with A3 or A4, so the
    # window can check the same one again after a fix.
    $state = [pscustomobject]@{ Answer = $null; Text = $null; Reports = @{}; Checks = @{}; Inputs = @{}; Error = $null; Refused = $false }
    $checksRun = 0
    for ($round = 0; $round -lt $script:AiMaxRounds; $round++) {
        Write-Dim (T 'ai.thinking')
        $r = Invoke-HcRelay @{ action = 'chat'; token = $script:HcToken; messages = @($history) }
        if (-not $r.Ok) { $state.Error = $r.Error; return $state }
        [void]$history.Add(@{ role = 'assistant'; content_json = [string]$r.Data.content_json })
        if ($r.Data.stop_reason -eq 'refusal') { $state.Refused = $true; return $state }

        $results = @()
        foreach ($block in @($r.Data.content)) {
            if ($block.type -eq 'text' -and $block.text) { $state.Text = $block.text }
            if ($block.type -ne 'tool_use') { continue }
            if ($block.name -eq 'give_answer') {
                $state.Answer = $block.input
                continue
            }
            $code = [string]$block.input.code
            $check = $null
            if ($checksRun -lt $script:AiMaxChecks) { $check = Get-HcAiCheck $code ([string]$block.input.input) }
            if ($null -eq $check) {
                $why = if ($checksRun -ge $script:AiMaxChecks) { 'The limit of checks for this conversation is reached; call give_answer now.' } else { "Check $code could not run with that input." }
                $results += @{ type = 'tool_result'; tool_use_id = $block.id; content = $why; is_error = $true }
                continue
            }
            $checksRun++
            Write-Step (T 'ai.running' $code (T "problem.$code"))
            $report = & $check
            $state.Reports[$code] = $report
            $state.Checks[$code] = $check
            $state.Inputs[$code] = [string]$block.input.input
            $results += @{ type = 'tool_result'; tool_use_id = $block.id; content = (Format-HcReportForAi $report) }
        }
        if ($state.Answer -or $results.Count -eq 0) { return $state }
        [void]$history.Add(@{ role = 'user'; content_json = (ConvertTo-HcContentJson $results) })
    }
    $state
}

function Invoke-HcAi {
    param([pscustomobject]$Environment, [string]$Text)
    Clear-HcScreen
    Write-Banner $Environment
    Write-Host ('  ?  ' + (T 'ai.title')) -ForegroundColor Yellow
    Write-Host ''
    if (-not $Environment.Online) {
        Write-Warn2 (T 'ai.offline')
        Write-Host ''
        [void](Read-HcLine (T 'pressEnter'))
        return
    }
    if (-not (Unlock-HcRelay)) {
        Write-Host ''
        [void](Read-HcLine (T 'pressEnter'))
        return
    }
    if ($Text) {
        Write-Dim (T 'ai.youTyped' $Text)
    } else {
        $Text = "$(Read-HcLine (T 'ai.describe'))".Trim()
        if (-not $Text -or $Text -eq 'Q') { return }
    }
    Write-Dim (T 'ai.privacy')
    Write-Host ''

    $state = Invoke-HcAiConversation $Text
    Write-Host ''
    if ($state.Error) {
        Write-Warn2 (Get-HcRelayMessage $state.Error)
    } elseif ($state.Refused) {
        Write-Warn2 (T 'ai.refused')
    } elseif (-not $state.Answer) {
        if ($state.Text) { Write-HcLabelled (T 'ai.answer') $state.Text 'Yellow' } else { Write-Warn2 (T 'ai.noAnswer') }
    } else {
        $a = $state.Answer
        Write-HcLabelled (T 'ai.answer') ([string]$a.summary) 'Yellow'
        Write-Dim (T ('ai.confidence.' + $a.confidence))
        $steps = @($a.steps | Where-Object { $_ })
        if ($steps.Count) {
            Write-Host ''
            Write-Host ('  ' + (T 'ai.steps')) -ForegroundColor Cyan
            for ($i = 0; $i -lt $steps.Count; $i++) { Write-HcLabelled "$($i + 1)." ([string]$steps[$i]) 'Cyan' }
        }
        $code = [string]$a.problem_code
        if ($state.Reports.ContainsKey($code)) {
            # The fixes the AI chose, from what that check offered, through the normal menu.
            $script:HcCurrentCode = $code
            Save-HcVisit $code $state.Reports[$code]
            Write-Host ''
            Write-HcReport $state.Reports[$code] -LinesOnly
            Invoke-HcReportLoop $code $state.Checks[$code] $state.Reports[$code] -OnlyFixes @($a.fix_ids | ForEach-Object { [string]$_ })
            return
        }
    }
    Write-Host ''
    [void](Read-HcLine (T 'pressEnter'))
}
'@


# The options, saved before the code loads: run as a file (a USB stick),
# this script's scope is Housecall's script: scope, and loading the code
# resets $script:Lang -- which is this same $Lang.
$HcOptions = @{ DryRun = [bool]$DryRun; Lang = $Lang; Start = $Start; NoAI = [bool]$NoAI; Console = [bool]$Console }

. ([scriptblock]::Create($HcSource))
$script:HcSource = $HcSource
$script:HcBuild = $HcBuild
# Run from a file (a USB stick) rather than through irm | iex.
$script:HcFromFile = [bool]$PSCommandPath
Start-Housecall -DryRun:$HcOptions.DryRun -Lang $HcOptions.Lang -Start $HcOptions.Start -NoAI:$HcOptions.NoAI -Console:$HcOptions.Console
